export const RAHPC_LAB_MOCKS: TestDef[] = [
  {
    country: 'RW', category: 'licensing-exams',
    profession: {"slug":"rahpc-biomedical-laboratory-sciences-licensing-exam","name":"Biomedical Laboratory Sciences Licensing Exam (RAHPC)"},
    slug: "rahpc-biomedical-laboratory-sciences-mock-exam-1",
    title: "Biomedical Laboratory Sciences Licensing Exam (RAHPC) — Mock Exam 1",
    summary: "Haematology and Immunohaematology; Microbiology; Clinical Chemistry; Histopathology and Laboratory Management.",
    free: true, difficulty: 'STANDARD', minutes: 60,
    instructions: ["50 multiple-choice questions, one best answer each, 60 minutes.","RAHPC does not publish the number of questions or the time of its registry exam; these mocks cover its published thematic areas."],
    sections: [{"name":"Haematology and Immunohaematology"},{"name":"Microbiology"},{"name":"Clinical Chemistry"},{"name":"Histopathology and Laboratory Management"}],
    questions: [
      {"section":"Haematology and Immunohaematology","topic":"Red Cell Indices","stem":"A woman's full blood count shows Hb 9.0 g/dL, haematocrit 30% and RBC 4.0 × 10^12/L. What is her MCV?","options":["22.5 fL","30 fL","75 fL","133 fL"],"correct":2,"explanation":"MCV = haematocrit (%) × 10 ÷ RBC (× 10^12/L) = 30 × 10 ÷ 4.0 = 75 fL, a microcytic value. 22.5 is her MCH in pg (Hb 9.0 × 10 ÷ 4.0), not the MCV."},
      {"section":"Haematology and Immunohaematology","topic":"Cold Agglutinin Artefact","stem":"An EDTA sample from a 60-year-old man gives RBC 2.2 × 10^12/L, Hb 11.8 g/dL, MCV 128 fL and MCHC 42 g/dL. The blood film shows clumps of red cells. What should the technologist do before reporting?","options":["Dilute the sample 1 in 2 with saline and double the RBC count","Warm the sample to 37 °C and re-run it promptly","Report a macrocytic anaemia and suggest B12 and folate tests","Recollect the blood in a sodium citrate tube and re-run it"],"correct":1,"explanation":"Cold agglutinins clump red cells, so the analyser counts clumps as single large cells: the RBC falls, the MCV rises and the MCHC becomes impossibly high (above about 37 g/dL). Warming to 37 °C disperses the clumps; recollecting in citrate is the fix for EDTA platelet clumping, not for cold agglutinins."},
      {"section":"Haematology and Immunohaematology","topic":"Pseudothrombocytopenia","stem":"A healthy 25-year-old woman has a platelet count of 38 × 10^9/L on an EDTA sample. She has no bruising or bleeding. The film shows large platelet clumps at the feathered edge. What is the best next step?","options":["Repeat the count on the same EDTA tube after 2 hours","Collect a new sample in sodium citrate and repeat the count","Report severe thrombocytopenia to the clinician as critical","Request a bone marrow aspirate"],"correct":1,"explanation":"Platelet clumps with a low count in a well person suggest EDTA-dependent pseudothrombocytopenia; a citrate sample usually prevents clumping (the count is corrected for the citrate dilution). Re-running the same EDTA tube does not help because clumping often gets worse with time."},
      {"section":"Haematology and Immunohaematology","topic":"Microcytosis Interpretation","stem":"A well 24-year-old woman has Hb 11.2 g/dL, RBC 6.1 × 10^12/L, MCV 62 fL and a normal RDW. What is the most likely cause of her microcytosis?","options":["Iron deficiency anaemia","Beta-thalassaemia trait","Anaemia of chronic disease","Sideroblastic anaemia"],"correct":1,"explanation":"A high RBC count with a very low MCV and normal RDW suggests thalassaemia trait; the Mentzer index (MCV ÷ RBC) = 62 ÷ 6.1 ≈ 10.2, and a value below 13 favours thalassaemia trait. Iron deficiency usually gives a low RBC count and a raised RDW; the trait is confirmed by a raised HbA2 on HPLC or electrophoresis."},
      {"section":"Haematology and Immunohaematology","topic":"NRBC Correction","stem":"An analyser that counts nucleated red cells (NRBC) as white cells reports a WBC of 22.0 × 10^9/L in a newborn. The blood film shows 60 NRBC per 100 white cells. What is the corrected WBC?","options":["35.2 × 10^9/L","8.8 × 10^9/L","13.8 × 10^9/L","22.0 × 10^9/L"],"correct":2,"explanation":"Corrected WBC = WBC × 100 ÷ (100 + NRBC per 100 WBC) = 22.0 × 100 ÷ 160 = 13.75 ≈ 13.8 × 10^9/L. Subtracting 60% of the count (giving 8.8) is wrong because the 60 NRBC are counted per 100 white cells, so they make up 60/160 of the total nucleated cells."},
      {"section":"Haematology and Immunohaematology","topic":"Manual WBC Count","stem":"For a manual WBC count, blood is diluted 1 in 20 in Türk's fluid. In an improved Neubauer chamber, 150 cells are counted in the 4 large corner squares (each 1 mm × 1 mm, depth 0.1 mm). What is the WBC count?","options":["3.0 × 10^9/L","0.75 × 10^9/L","75 × 10^9/L","7.5 × 10^9/L"],"correct":3,"explanation":"Volume counted = 4 × (1 × 1 × 0.1) mm³ = 0.4 µL. WBC = 150 ÷ 0.4 × 20 = 7,500 per µL = 7.5 × 10^9/L. The answer 3.0 comes from multiplying by the dilution (150 × 20) but forgetting to divide by the volume counted."},
      {"section":"Haematology and Immunohaematology","topic":"Reticulocyte Count Correction","stem":"A 30-year-old woman with haemolysis has a reticulocyte count of 6% and a haematocrit of 15%. Taking 45% as a normal haematocrit, what is her corrected reticulocyte count?","options":["2%","18%","3%","6%"],"correct":0,"explanation":"Corrected reticulocyte count = reticulocyte % × patient haematocrit ÷ normal haematocrit = 6 × 15 ÷ 45 = 2%. The answer 18% comes from turning the ratio upside down (6 × 45 ÷ 15)."},
      {"section":"Haematology and Immunohaematology","topic":"Red Cell Inclusions","stem":"A blood film from a 9-year-old boy with sickle cell disease (HbSS) shows many red cells with one small, round, dark purple inclusion near the edge of the cell. What best explains this finding?","options":["Lead poisoning","Malaria infection","Loss of spleen function","Iron overload"],"correct":2,"explanation":"These are Howell–Jolly bodies (DNA remnants), which a working spleen normally removes; repeated splenic infarction in HbSS causes functional asplenia. They can be mistaken for malaria parasites, but a ring form has a ring of blue cytoplasm with a chromatin dot, not a single solid round body."},
      {"section":"Haematology and Immunohaematology","topic":"Red Cell Fragments","stem":"A 35-year-old woman has fever, confusion and a raised creatinine. Results: Hb 7.8 g/dL, platelets 18 × 10^9/L, PT and APTT normal, fibrinogen normal. The film shows many red cell fragments. What is the most likely diagnosis?","options":["Immune thrombocytopenia","Disseminated intravascular coagulation","Thrombotic thrombocytopenic purpura","Hereditary spherocytosis"],"correct":2,"explanation":"Red cell fragments (schistocytes) with severe thrombocytopenia but normal clotting tests point to TTP, a medical emergency. DIC also gives fragments, but the PT and APTT are prolonged and fibrinogen is low; ITP does not produce fragments."},
      {"section":"Haematology and Immunohaematology","topic":"Basophilic Stippling","stem":"A 40-year-old man who recycles car batteries has abdominal pain and anaemia (Hb 9.6 g/dL, MCV 74 fL). His Leishman-stained film shows many red cells containing small blue dots (basophilic stippling). Which test best supports the likely diagnosis?","options":["Blood lead level","Serum vitamin B12","Direct antiglobulin test","Haemoglobin electrophoresis"],"correct":0,"explanation":"Basophilic stippling (clumped ribosomal RNA) with anaemia, abdominal pain and battery work strongly suggests lead poisoning, which blocks pyrimidine 5'-nucleotidase and haem synthesis. Thalassaemia can also show stippling, but the exposure history makes lead the most likely cause."},
      {"section":"Haematology and Immunohaematology","topic":"Heinz Bodies","stem":"Two days after starting an oxidant drug, a man passes dark urine. His film shows bite cells and blister cells. Which stain best shows the red cell inclusions that cause these changes?","options":["Leishman stain","Perls' Prussian blue","Periodic acid–Schiff (PAS)","Supravital methyl violet"],"correct":3,"explanation":"In G6PD deficiency, oxidant drugs denature haemoglobin into Heinz bodies, which are seen only with a supravital stain such as methyl violet; the spleen removes them and leaves bite cells. Perls' stain shows iron granules (Pappenheimer bodies), not Heinz bodies."},
      {"section":"Haematology and Immunohaematology","topic":"Macrocytic Film Features","stem":"A 58-year-old woman has Hb 8.0 g/dL and MCV 118 fL. Her film shows oval macrocytes and neutrophils with six or more nuclear lobes. What is the most likely cause?","options":["Myelofibrosis","Alcoholic liver disease","Iron deficiency","Vitamin B12 or folate deficiency"],"correct":3,"explanation":"Oval macrocytes with hypersegmented neutrophils are the classic film of megaloblastic anaemia from B12 or folate deficiency. Alcohol and liver disease give round macrocytes and target cells, usually without hypersegmented neutrophils and rarely with an MCV this high."},
      {"section":"Haematology and Immunohaematology","topic":"Romanowsky Staining","stem":"A batch of Leishman-stained blood films looks too blue: the red cells are blue-grey and the neutrophil granules are hard to see. What is the most likely cause?","options":["Stain diluted too much with buffer","Buffer pH too acidic","Buffer pH too alkaline","Fixation in methanol for too long"],"correct":2,"explanation":"An alkaline buffer (pH well above 6.8) makes the whole film too blue. An acidic buffer gives the opposite picture: bright red cells and pale, poorly stained nuclei."},
      {"section":"Microbiology","topic":"Gram Stain Errors","stem":"A technician Gram-stains a smear from a fresh overnight culture of Staphylococcus aureus as a control. The cocci appear pink-red. What is the most likely cause?","options":["The safranin counterstain was left on too long","The Lugol's iodine was left on too long","The acetone-alcohol decolouriser was left on too long","The smear was heat-fixed before staining"],"correct":2,"explanation":"Too much decolouriser washes the crystal violet–iodine complex out of Gram-positive cells, so they take up the red counterstain. Leaving safranin on longer cannot remove the purple complex already held in the cell."},
      {"section":"Microbiology","topic":"AFB Smear Grading","stem":"A Ziehl–Neelsen sputum smear shows 25 acid-fast bacilli in 100 oil-immersion fields. How should the result be reported?","options":["1+","3+","Scanty (25 AFB per 100 fields)","2+"],"correct":0,"explanation":"WHO/IUATLD grading: 1–9 AFB per 100 fields = scanty, 10–99 per 100 fields = 1+, 1–10 per field = 2+, more than 10 per field = 3+. So 25 per 100 fields is 1+, not scanty."},
      {"section":"Microbiology","topic":"AFB Negative Smear","stem":"Before a Ziehl–Neelsen sputum smear is reported as \"No AFB seen\", at least how many oil-immersion fields must be examined?","options":["10 fields","20 fields","100 fields","50 fields"],"correct":2,"explanation":"At least 100 fields (about one length of a 2 cm smear) are read at x1000 before reporting negative. Stopping at 20–50 fields misses low-grade (scanty) positives."},
      {"section":"Microbiology","topic":"MacConkey Agar","stem":"A midstream urine from a woman with dysuria grows pink, lactose-fermenting colonies on MacConkey agar. Which organism is most likely?","options":["Proteus mirabilis","Salmonella Typhi","Pseudomonas aeruginosa","Escherichia coli"],"correct":3,"explanation":"E. coli ferments lactose, and the acid turns the neutral red indicator pink. Proteus is also a common urinary pathogen, but it does not ferment lactose and gives pale colonies, like Pseudomonas and Salmonella."},
      {"section":"Microbiology","topic":"Chocolate Agar","stem":"CSF from a 2-year-old child with suspected meningitis is plated on chocolate agar and incubated in a candle jar. Why is chocolate agar used?","options":["It inhibits Gram-positive skin commensals","It separates lactose fermenters from non-fermenters","It shows the type of haemolysis produced by pneumococci","It supplies X (haemin) and V (NAD) factors needed by Haemophilus influenzae"],"correct":3,"explanation":"Heating blood releases the X and V factors that H. influenzae needs, and the medium also supports Neisseria meningitidis. Haemolysis is read on blood agar, not on chocolate agar, where the red cells are already lysed."},
      {"section":"Microbiology","topic":"Cholera Culture","stem":"A rice-water stool from a suspected cholera case is to be cultured on TCBS agar. Which enrichment broth should also be inoculated?","options":["Alkaline peptone water","Brain–heart infusion broth","Selenite F broth","Thioglycollate broth"],"correct":0,"explanation":"Alkaline peptone water (about pH 8.6) favours Vibrio cholerae and holds back other gut bacteria. Selenite F is the enrichment broth for Salmonella, not Vibrio."},
      {"section":"Microbiology","topic":"Staphylococcus Identification","stem":"Gram-positive cocci in clusters grown from a pus swab are catalase positive. Which test best confirms Staphylococcus aureus?","options":["Bacitracin test","Coagulase test","Oxidase test","Optochin test"],"correct":1,"explanation":"Catalase separates staphylococci from streptococci; coagulase then separates S. aureus (positive) from coagulase-negative staphylococci. Optochin identifies Streptococcus pneumoniae, not staphylococci."},
      {"section":"Microbiology","topic":"Kligler Iron Agar","stem":"A Gram-negative rod from a stool culture is lactose negative, oxidase negative and urease negative. In Kligler iron agar it gives a red (alkaline) slant, yellow (acid) butt and blackening. Which organism is most likely?","options":["Shigella species","Escherichia coli","Pseudomonas aeruginosa","Salmonella species"],"correct":3,"explanation":"Alkaline slant, acid butt and H2S (black) in a urease-negative, oxidase-negative rod suggest Salmonella; confirm with serology. Shigella gives the same slant/butt reaction but no H2S."},
      {"section":"Microbiology","topic":"Pseudomonas Identification","stem":"Gram-negative rods from a burn wound produce a green pigment, have a grape-like smell, do not ferment lactose and are oxidase positive. Which organism is this?","options":["Escherichia coli","Klebsiella pneumoniae","Pseudomonas aeruginosa","Proteus mirabilis"],"correct":2,"explanation":"Green pigment, grape-like odour and a positive oxidase test are typical of P. aeruginosa. Proteus is also a lactose non-fermenter found in wounds, but it is oxidase negative."},
      {"section":"Microbiology","topic":"Disc Diffusion Inoculum","stem":"When setting up a disc diffusion (Kirby–Bauer) test, the inoculum is made much heavier than the 0.5 McFarland standard. What will happen to the results?","options":["Only the control strain zones will be affected","Zones will be larger, so resistant isolates may be reported susceptible","Zones will be smaller, so susceptible isolates may be reported resistant","Zones will not change because agar depth controls diffusion"],"correct":2,"explanation":"A heavy inoculum grows closer to the disc, giving smaller zones and false resistance. Larger zones (false susceptibility) come from too light an inoculum, not too heavy."},
      {"section":"Microbiology","topic":"MRSA Detection","stem":"Which antibiotic disc is used in routine disc diffusion testing to detect methicillin (oxacillin) resistance in Staphylococcus aureus?","options":["Cefoxitin","Vancomycin","Penicillin","Ceftriaxone"],"correct":0,"explanation":"The cefoxitin disc is the recommended surrogate test for mecA-mediated methicillin resistance. Vancomycin disc diffusion is not reliable for staphylococci and needs an MIC method."},
      {"section":"Microbiology","topic":"ESBL Detection","stem":"An E. coli isolate shows a clear widening of the cefotaxime zone on the side facing an amoxicillin–clavulanic acid disc. What does this show?","options":["Methicillin resistance","Inducible clindamycin resistance","Production of extended-spectrum beta-lactamase (ESBL)","A mixed culture with a second organism"],"correct":2,"explanation":"Clavulanic acid inhibits ESBL enzymes, so cefotaxime works better near that disc (double-disc synergy). Inducible clindamycin resistance is a staphylococcal pattern: a flattened clindamycin zone next to erythromycin."},
      {"section":"Microbiology","topic":"Urine Colony Count","stem":"A 1 µL calibrated loop is used to plate a midstream urine. After overnight incubation, 150 colonies of one organism grow. What is the colony count?","options":["1.5 × 10^3 CFU/mL","1.5 × 10^4 CFU/mL","1.5 × 10^5 CFU/mL","1.5 × 10^6 CFU/mL"],"correct":2,"explanation":"1 µL is 1/1000 mL, so CFU/mL = 150 × 1000 = 150 000 = 1.5 × 10^5, which is significant bacteriuria (10^5/mL or more). Multiplying by 100 instead of 1000 gives the wrong figure of 1.5 × 10^4."},
      {"section":"Clinical Chemistry","topic":"Glucose Sample Delay","stem":"Blood for a fasting glucose is taken at a health centre into a plain tube. It reaches the district hospital laboratory 4 hours later, not separated. The result is 3.1 mmol/L, but the patient had no symptoms of hypoglycaemia. What is the most likely explanation?","options":["Blood cells used up glucose in the tube before analysis","The patient had eaten breakfast before the test","Haemolysis released extra water from red cells into the serum","The sample evaporated during the long transport"],"correct":0,"explanation":"Red and white cells keep breaking down glucose (glycolysis) in an unseparated sample with no inhibitor, so the glucose falls with time at room temperature. Eating before the test would raise the result, not lower it; glucose should be taken into a fluoride oxalate tube or separated quickly."},
      {"section":"Clinical Chemistry","topic":"Fluoride Oxalate Tube","stem":"A grey-top tube contains sodium fluoride and potassium oxalate. What is the role of the sodium fluoride?","options":["It binds calcium so the blood does not clot","It inhibits glucose oxidase in the reagent","It lowers the pH so bacteria cannot grow","It inhibits the glycolytic enzyme enolase"],"correct":3,"explanation":"Fluoride stops glycolysis by inhibiting enolase, which preserves glucose in the sample. Binding calcium to prevent clotting is the job of the oxalate, not the fluoride."},
      {"section":"Clinical Chemistry","topic":"Confirming Diabetes Diagnosis","stem":"A 45-year-old man with no symptoms has a fasting plasma glucose of 7.4 mmol/L at a routine check-up. Following WHO criteria, what is the best next step?","options":["Repeat the test only if he later develops symptoms","Diagnose diabetes now on this single result","Report impaired fasting glucose and recheck in one year","Confirm with a repeat diagnostic test on another day"],"correct":3,"explanation":"A fasting glucose of 7.0 mmol/L or more is in the diabetic range, but in a person without symptoms one abnormal result must be confirmed by a repeat test (fasting glucose, OGTT or HbA1c) on a different day. 7.4 mmol/L is above the WHO impaired fasting glucose range (6.1-6.9 mmol/L), so that label is wrong."},
      {"section":"Clinical Chemistry","topic":"HbA1c Interference","stem":"A 30-year-old woman with sickle cell disease and diabetes has an HbA1c of 5.2% (33 mmol/mol). Her finger-prick glucose readings are often 12-15 mmol/L. What is the most likely reason for the low HbA1c?","options":["Fasting before the blood test lowered her HbA1c","Her glucose meter reads falsely high in sickle cell disease","Short red cell lifespan gives less time for glycation","HbA1c reflects only the last 2 weeks of glucose"],"correct":2,"explanation":"HbA1c depends on red cells living about 120 days; in haemolytic conditions such as sickle cell disease the cells are younger, so HbA1c is falsely low. HbA1c reflects about 2-3 months and is not affected by a single fast; glucose monitoring or fructosamine is better in such patients."},
      {"section":"Clinical Chemistry","topic":"Gestational Diabetes OGTT","stem":"A woman at 26 weeks of pregnancy has a 75 g OGTT. Results: fasting 5.4 mmol/L, 1 hour 9.6 mmol/L, 2 hours 7.9 mmol/L. WHO 2013 criteria for gestational diabetes are: fasting 5.1-6.9, 1 hour 10.0 or more, or 2 hours 8.5-11.0 mmol/L. How should these results be interpreted?","options":["Gestational diabetes only if the 2-hour value is also high","Overt diabetes, because the fasting value is above 5.1","Gestational diabetes, because one value meets the criteria","Normal, because two of the three values are normal"],"correct":2,"explanation":"Under WHO 2013 criteria, any ONE value at or above the threshold is enough; fasting 5.4 mmol/L is in the 5.1-6.9 range, so this is gestational diabetes. Overt diabetes in pregnancy needs a fasting value of 7.0 mmol/L or more."},
      {"section":"Clinical Chemistry","topic":"OGTT Patient Preparation","stem":"A clinician requests a standard 75 g oral glucose tolerance test for a non-pregnant adult. Which procedure is correct?","options":["Overnight fast, 75 g glucose in about 250-300 mL water sipped over 1 hour, samples at 0 and 2 hours","Light breakfast, 75 g glucose in about 250-300 mL water drunk within 5 minutes, samples at 0 and 2 hours","Overnight fast, 75 g glucose in about 250-300 mL water drunk within 5 minutes, samples at 0 and 2 hours","Overnight fast, 50 g glucose in about 200 mL water drunk within 5 minutes, samples at 0 and 1 hour"],"correct":2,"explanation":"The WHO OGTT is done after an overnight fast (about 8-14 hours); the patient drinks 75 g glucose in 250-300 mL water over 5 minutes, and plasma glucose is measured fasting and 2 hours after the start of the drink. The 50 g, 1-hour test is a pregnancy screening test, not the diagnostic OGTT."},
      {"section":"Clinical Chemistry","topic":"Creatinine Clearance","stem":"A 24-hour urine collection has a volume of 1,440 mL. Urine creatinine is 8.8 mmol/L and plasma creatinine is 88 µmol/L. What is the creatinine clearance?","options":["0.1 mL/min","144 mL/min","100 mL/min","10 mL/min"],"correct":2,"explanation":"Clearance = (U x V) / P with U and P in the same units. U = 8.8 mmol/L = 8,800 µmol/L; V = 1,440 mL / 1,440 min = 1.0 mL/min; so 8,800 x 1.0 / 88 = 100 mL/min. Forgetting to convert mmol/L to µmol/L gives 0.1 mL/min."},
      {"section":"Clinical Chemistry","topic":"Jaffe Method Interference","stem":"A patient in diabetic ketoacidosis has a serum creatinine of 210 µmol/L by the Jaffe (alkaline picrate) method. Two days later, after the ketoacidosis has resolved, it is 105 µmol/L. Apart from rehydration, which analytical factor most likely raised the first result?","options":["Acetoacetate reacting with the alkaline picrate reagent","Insulin treatment stopping creatinine production","Bilirubin reacting with the alkaline picrate reagent","Lipaemia scattering light at the reading wavelength"],"correct":0,"explanation":"Acetoacetate forms a coloured product with alkaline picrate, so the Jaffe method over-reads creatinine in ketoacidosis; enzymatic creatinine methods avoid this. Bilirubin causes a negative (falsely low) interference in the Jaffe reaction, not a positive one."},
      {"section":"Clinical Chemistry","topic":"Raised Urea After Bleeding","stem":"A 50-year-old man is admitted after vomiting blood. Urea is 24 mmol/L and creatinine is 105 µmol/L (reference 60-110 µmol/L). What best explains the high urea with a normal creatinine?","options":["Low muscle mass has lowered urea clearance","Digestion of blood protein in the gut produces extra urea","Severe liver failure has increased urea production","Acute tubular necrosis has damaged the kidneys"],"correct":1,"explanation":"Blood in the upper gut is digested like a high-protein meal, and the liver turns the absorbed amino acids into urea; volume loss adds a pre-renal effect. Acute tubular necrosis would also raise creatinine, and liver failure lowers urea because the liver makes it."},
      {"section":"Clinical Chemistry","topic":"CKD GFR Category","stem":"A 60-year-old woman has an eGFR of 38 mL/min/1.73 m² on two tests four months apart. Her urine albumin-creatinine ratio is 2 mg/mmol. Using KDIGO categories, what is her GFR category?","options":["G3b","G2","G3a","G4"],"correct":0,"explanation":"KDIGO GFR categories: G3a = 45-59, G3b = 30-44, G4 = 15-29 mL/min/1.73 m². An eGFR of 38 lasting more than 3 months is G3b; G3a starts at 45."},
      {"section":"Clinical Chemistry","topic":"Albumin-Creatinine Ratio","stem":"A man with type 2 diabetes has a urine albumin-creatinine ratio (ACR) of 12 mg/mmol on an early-morning sample. His dipstick protein is negative. What is the best interpretation?","options":["Moderately increased albuminuria; confirm on repeat samples","Invalid result; only a 24-hour urine protein is acceptable","Severely increased albuminuria; refer at once for kidney biopsy","Normal result, because the dipstick protein test is negative"],"correct":0,"explanation":"KDIGO albuminuria categories are A1 below 3, A2 3-30 and A3 above 30 mg/mmol, so 12 mg/mmol is A2 (moderately increased) and should be confirmed in 2 of 3 samples. A routine dipstick only turns positive at higher albumin levels, so a negative dipstick does not exclude this."},
      {"section":"Clinical Chemistry","topic":"Creatinine and Muscle Mass","stem":"An 82-year-old, very thin, bed-bound woman has a serum creatinine of 58 µmol/L (reference 45-90 µmol/L). Why may this \"normal\" creatinine overestimate her kidney function?","options":["Elderly kidneys reabsorb creatinine in the tubules","Bed rest increases creatinine loss in sweat","Her small muscle mass produces less creatinine","A low-salt diet lowers serum creatinine"],"correct":2,"explanation":"Creatinine comes from muscle, so a person with little muscle makes less of it and can have a \"normal\" serum creatinine despite a reduced GFR. Creatinine is not reabsorbed by the tubules; cystatin C, which does not depend on muscle mass, can help in such patients."},
      {"section":"Histopathology and Laboratory Management","topic":"Formalin Pigment","stem":"Sections of a blood-rich spleen show fine brown-black granules lying on top of the tissue, outside the cells. They are birefringent in polarised light. The lab had used old, unbuffered formalin. What are the granules most likely to be?","options":["Haemosiderin from old bleeding","Melanin pigment","Mercury pigment from the fixative","Acid formaldehyde haematin (formalin pigment)"],"correct":3,"explanation":"Unbuffered formalin becomes acidic (formic acid) and reacts with haemoglobin in blood-rich tissue to form acid formaldehyde haematin, which lies on the tissue and is birefringent; neutral buffered formalin prevents it. Haemosiderin is the tempting choice, but it lies inside macrophages and is Perls-positive."},
      {"section":"Histopathology and Laboratory Management","topic":"Fixative Volume and Penetration","stem":"A large fibroid uterus arrives in a small jar with a little formalin. On grossing two days later, the centre is soft and pale and its sections show poor nuclear staining. What would best have prevented this?","options":["Keeping the uterus in saline in the fridge until grossing","Slicing the specimen open and using about 10-20 times its volume of formalin","Changing the formalin for 70% alcohol after one hour","Using undiluted 40% formaldehyde instead of 10% formalin"],"correct":1,"explanation":"Formalin penetrates slowly, so a large unopened specimen in too little fixative autolyses in the centre; opening it and using an adequate volume (about 10-20 times the tissue) lets fixative reach all parts. Concentrated 40% formaldehyde does not penetrate better and causes artefacts and extra hazard."},
      {"section":"Histopathology and Laboratory Management","topic":"Fixative for Electron Microscopy","stem":"A renal biopsy is divided for light microscopy, immunofluorescence and electron microscopy. Which fixative should be used for the electron microscopy portion?","options":["Buffered glutaraldehyde","Carnoy's fluid","10% neutral buffered formalin","Bouin's fluid"],"correct":0,"explanation":"Glutaraldehyde cross-links proteins quickly and tightly, giving the fine ultrastructural preservation needed for electron microscopy. Neutral buffered formalin is right for the light-microscopy portion but preserves ultrastructure poorly."},
      {"section":"Histopathology and Laboratory Management","topic":"Breast Specimen Fixation Time","stem":"A mastectomy specimen for breast carcinoma will be tested for ER, PR and HER2. Which handling meets the ASCO/CAP recommendations?","options":["Put in 70% alcohol within 1 hour and fixed for 24 hours","Kept overnight in saline in the fridge, then fixed for 24 hours","Put in 10% neutral buffered formalin within 1 hour of removal and fixed for 6-72 hours","Put in formalin within 6 hours of removal and fixed for 1-2 hours"],"correct":2,"explanation":"ASCO/CAP guidelines require a cold ischaemia time of 1 hour or less and fixation in 10% NBF for 6-72 hours; shorter or longer fixation, or delay, can give false-negative receptor results. The 1-2 hour option is tempting because it is fast, but under-fixation gives unreliable staining."},
      {"section":"Histopathology and Laboratory Management","topic":"Incomplete Dehydration","stem":"During manual processing, a tissue block is moved from \"absolute\" alcohol into xylene and the xylene turns milky. What is the most likely cause?","options":["Water is still in the tissue because the alcohol was not truly absolute","The xylene is too cold for clearing","The tissue was fixed for too long in formalin","Paraffin wax has contaminated the xylene"],"correct":0,"explanation":"Xylene does not mix with water, so a milky (turbid) appearance means water remains in the tissue from diluted or exhausted alcohol; the block should go back into fresh absolute alcohol. Over-fixation makes tissue hard but does not make xylene cloudy."},
      {"section":"Histopathology and Laboratory Management","topic":"Wax Infiltration Temperature","stem":"The paraffin oven of a tissue processor is set far above the melting point of the wax. What will most likely happen to the tissue?","options":["It becomes soft and mushy and cannot be trimmed","The wax fails to enter the tissue at all","It becomes hard, brittle and shrunken, and is difficult to cut","It cuts more easily into thin ribbons"],"correct":2,"explanation":"Infiltration should be done only a few degrees above the wax melting point; overheating causes the tissue to harden, shrink and become brittle, giving poor sections. Soft, mushy tissue is a sign of poor fixation or incomplete processing, not overheated wax."},
      {"section":"Histopathology and Laboratory Management","topic":"Decalcification Endpoint","stem":"A femoral head is being decalcified in acid. Which method gives the most accurate check that decalcification is complete?","options":["Pricking the bone with a needle","Bending the specimen by hand","Taking an X-ray (radiograph) of the specimen","Leaving it for a fixed 48 hours"],"correct":2,"explanation":"Radiography shows any remaining calcium deposits and is the most accurate end-point test (a chemical test of the used acid for calcium is also reliable). Needle pricking is a crude physical test that damages the tissue and misses small calcified areas."},
      {"section":"Histopathology and Laboratory Management","topic":"Choice of Decalcifying Agent","stem":"A bone biopsy needs good morphology and may later need immunohistochemistry and molecular tests. Time is not urgent. Which decalcifying agent is best?","options":["5% nitric acid","Formic acid with heat","Strong hydrochloric acid","EDTA (a chelating agent)"],"correct":3,"explanation":"EDTA removes calcium by chelation; it is slow but gives the best preservation of morphology, antigens and nucleic acids. Nitric acid is much faster but damages staining, antigens and DNA, so it is the wrong choice when further tests are planned."},
      {"section":"Histopathology and Laboratory Management","topic":"Chatter Artefact","stem":"Paraffin sections show alternating thick and thin bands running parallel to the knife edge, like a venetian blind. What is the most likely cause?","options":["Water bath temperature too low","Vibration from a loose blade or block clamp","Section thickness set too high","A nick in the knife edge"],"correct":1,"explanation":"Chatter comes from vibration during cutting, due to a loose blade or block, or tissue that is too hard. A nick in the blade gives lines at right angles to the knife edge, not bands parallel to it."},
      {"section":"Histopathology and Laboratory Management","topic":"Scored Sections","stem":"Every section in a ribbon has a split running at right angles to the knife edge, always in the same place. What should the technician do?","options":["Tighten the block clamp","Move to an unused part of the blade or replace the blade","Cool the block on ice for longer","Reduce the section thickness"],"correct":1,"explanation":"A split or score in the same place in every section comes from a nick or debris on the blade edge, so a fresh part of the blade is needed. Tightening the clamp fixes vibration (chatter), not scoring."},
      {"section":"Histopathology and Laboratory Management","topic":"Ribbon Failure","stem":"In a cold room, paraffin sections come off one by one and will not join into a ribbon. The blade is new. What is the most likely cause?","options":["The water bath is too hot","The block face has become too warm","The tissue was fixed for too long","The wax is too hard at this room temperature"],"correct":3,"explanation":"Sections join into a ribbon because their edges slightly soften and stick; wax that is too hard for a cold room will not do this, so warming the block face slightly or using a softer wax helps. A warm block face causes compression and sticking, the opposite problem."},
      {"section":"Histopathology and Laboratory Management","topic":"Curved Ribbon","stem":"A paraffin ribbon curves to one side instead of running straight. What is the most likely cause?","options":["The tissue was not fully fixed","The section thickness setting is too thin","The upper and lower edges of the block face are not parallel","The water bath contains too much adhesive"],"correct":2,"explanation":"If the top and bottom edges of the block are not parallel, each section is wider on one side, so the ribbon curves; trimming the edges parallel fixes it. Poor fixation affects tissue quality, not the shape of the ribbon."},
    ],
  },
  {
    country: 'RW', category: 'licensing-exams',
    profession: {"slug":"rahpc-biomedical-laboratory-sciences-licensing-exam","name":"Biomedical Laboratory Sciences Licensing Exam (RAHPC)"},
    slug: "rahpc-biomedical-laboratory-sciences-mock-exam-2",
    title: "Biomedical Laboratory Sciences Licensing Exam (RAHPC) — Mock Exam 2",
    summary: "Haematology and Immunohaematology; Microbiology; Clinical Chemistry; Histopathology and Laboratory Management.",
    free: false, difficulty: 'STANDARD', minutes: 60,
    instructions: ["50 multiple-choice questions, one best answer each, 60 minutes.","RAHPC does not publish the number of questions or the time of its registry exam; these mocks cover its published thematic areas."],
    sections: [{"name":"Haematology and Immunohaematology"},{"name":"Microbiology"},{"name":"Clinical Chemistry"},{"name":"Histopathology and Laboratory Management"}],
    questions: [
      {"section":"Haematology and Immunohaematology","topic":"Iron Deficiency Tests","stem":"A 32-year-old woman with heavy periods has Hb 8.5 g/dL and MCV 68 fL. She has no infection or inflammatory disease. Which single test best confirms iron deficiency?","options":["Serum ferritin","Total iron-binding capacity","Serum iron","Red cell distribution width"],"correct":0,"explanation":"A low serum ferritin reflects low body iron stores and is the most specific single test for iron deficiency when there is no inflammation. Serum iron varies through the day and also falls in infection and chronic disease, so it is less reliable."},
      {"section":"Haematology and Immunohaematology","topic":"Anaemia of Chronic Disease","stem":"A 55-year-old woman with long-standing rheumatoid arthritis has Hb 9.5 g/dL, MCV 79 fL, low serum iron, low TIBC and a raised ferritin. What is the most likely type of anaemia?","options":["Anaemia of chronic disease","Beta-thalassaemia trait","Iron deficiency anaemia","Sideroblastic anaemia"],"correct":0,"explanation":"In anaemia of chronic disease, hepcidin traps iron in macrophages: serum iron is low, but TIBC is low and ferritin is normal or raised. In iron deficiency, TIBC is high and ferritin is low."},
      {"section":"Haematology and Immunohaematology","topic":"Sickle Cell Testing","stem":"A sickle solubility test is positive for a 19-year-old student. Which test should be done next to tell sickle cell trait (HbAS) from sickle cell disease (HbSS)?","options":["Repeat the solubility test with fresh reagent","Sodium metabisulphite sickling slide test","Haemoglobin electrophoresis or HPLC","Osmotic fragility test"],"correct":2,"explanation":"Solubility and sickling slide tests detect any HbS, so both are positive in AS and SS. Electrophoresis or HPLC separates the haemoglobins: HbAS shows HbA plus HbS, while HbSS shows HbS with no HbA."},
      {"section":"Haematology and Immunohaematology","topic":"Spherocytic Anaemias","stem":"A 6-year-old boy has jaundice, splenomegaly and many spherocytes on his film. His father had his spleen removed for 'anaemia'. Which result best separates hereditary spherocytosis from autoimmune haemolytic anaemia?","options":["Negative direct antiglobulin test","Increased osmotic fragility","Low serum haptoglobin","Raised reticulocyte count"],"correct":0,"explanation":"A negative DAT shows the red cells are not coated with antibody or complement, which points away from autoimmune haemolysis and supports HS. Increased osmotic fragility is tempting, but any spherocytes are fragile, so it is also increased in AIHA; reticulocytes and haptoglobin change in both."},
      {"section":"Haematology and Immunohaematology","topic":"G6PD Testing","stem":"A boy has acute haemolysis after taking an oxidant drug. A G6PD screening test done during the episode, when his reticulocyte count is 12%, gives a normal result. What is the best interpretation?","options":["The reagent has expired and the test must be repeated today","The haemolysis must be immune, so a DAT is the only test needed","The result may be falsely normal; repeat the test after recovery","G6PD deficiency is excluded"],"correct":2,"explanation":"During and just after haemolysis the oldest, most deficient cells have been destroyed, and young red cells and reticulocytes have higher G6PD activity, so a deficient patient can test normal. The test should be repeated some weeks after recovery (often about 3 months) when the cell population has returned to normal."},
      {"section":"Haematology and Immunohaematology","topic":"Markers of Haemolysis","stem":"Which finding most specifically shows that haemolysis is intravascular rather than extravascular?","options":["Spherocytes on the blood film","Raised reticulocyte count","Raised unconjugated bilirubin","Haemosiderin in the urine"],"correct":3,"explanation":"Free haemoglobin released into the plasma is filtered by the kidneys and stored in tubular cells, which are shed as urinary haemosiderin; this happens only when haemolysis is intravascular. Raised bilirubin and reticulocytes occur in both types, and spherocytes usually suggest extravascular destruction."},
      {"section":"Haematology and Immunohaematology","topic":"Auer Rods","stem":"A bone marrow film from a 45-year-old man shows many blasts. Some blasts contain thin, pink-red, needle-shaped rods in the cytoplasm. What do these rods indicate?","options":["The blasts are myeloid","Chronic lymphocytic leukaemia","The blasts are lymphoid","A reactive change after infection"],"correct":0,"explanation":"Auer rods are fused primary (azurophilic) granules and are found only in myeloid blasts, as in AML. They are never seen in lymphoblasts, so their presence rules against ALL."},
      {"section":"Haematology and Immunohaematology","topic":"Acute Promyelocytic Leukaemia","stem":"A 28-year-old woman has bleeding gums and bruises. Platelets are 20 × 10^9/L, PT and APTT are prolonged and fibrinogen is very low. Her marrow is full of abnormal promyelocytes, some with bundles of Auer rods. Which genetic change confirms the diagnosis?","options":["t(9;22) BCR-ABL1","t(8;14) MYC-IGH","t(15;17) PML-RARA","Trisomy 21"],"correct":2,"explanation":"Abnormal promyelocytes with bundles of Auer rods and DIC indicate acute promyelocytic leukaemia, defined by t(15;17) PML-RARA; it is an emergency because of the bleeding risk. t(9;22) is the Philadelphia translocation of CML, and t(8;14) is typical of Burkitt lymphoma."},
      {"section":"Haematology and Immunohaematology","topic":"Chronic Myeloid Leukaemia","stem":"A 50-year-old man has a large spleen and a WBC of 185 × 10^9/L. The film shows myeloid cells at all stages, with peaks of myelocytes and neutrophils, and increased basophils. Which test confirms the most likely diagnosis?","options":["BCR-ABL1 by PCR or FISH","Myeloperoxidase stain","Bone marrow Perls' stain","Flow cytometry for CD5 and CD23"],"correct":0,"explanation":"This film is typical of chronic myeloid leukaemia, which is confirmed by finding the BCR-ABL1 fusion (Philadelphia chromosome, t(9;22)). A myeloperoxidase stain only shows the cells are myeloid; CD5 and CD23 are used to diagnose CLL."},
      {"section":"Haematology and Immunohaematology","topic":"Chronic Lymphocytic Leukaemia","stem":"A 68-year-old man has lymphocytes of 45 × 10^9/L. The film shows small, mature-looking lymphocytes and many smudge cells. Which immunophenotype supports the most likely diagnosis?","options":["CD10+, CD19+, TdT+ cells","CD5+, CD19+, CD23+ B cells","CD34+, CD13+, CD33+ cells","CD3+, CD4+ T cells"],"correct":1,"explanation":"CLL cells are B cells (CD19+) that also express CD5 and CD23, with weak surface immunoglobulin. CD10 with TdT marks precursor B lymphoblasts (B-ALL), and CD34, CD13 and CD33 mark myeloid blasts."},
      {"section":"Haematology and Immunohaematology","topic":"Acute Lymphoblastic Leukaemia","stem":"A 5-year-old girl has fever, bone pain and pallor. Her film shows many small blasts with scanty cytoplasm and no granules. The blasts are myeloperoxidase negative and TdT positive. What is the most likely diagnosis?","options":["Leukaemoid reaction","Acute lymphoblastic leukaemia","Acute myeloid leukaemia","Chronic myeloid leukaemia"],"correct":1,"explanation":"ALL is the commonest leukaemia of childhood; TdT is a marker of immature lymphoid cells and the blasts lack myeloperoxidase. AML blasts are typically myeloperoxidase positive and may contain granules or Auer rods."},
      {"section":"Haematology and Immunohaematology","topic":"Leukaemoid Reaction","stem":"A 40-year-old man with severe pneumonia has a WBC of 48 × 10^9/L. The film shows mostly neutrophils and band forms with toxic granulation and Döhle bodies, a few metamyelocytes, no blasts and no increase in basophils. What is the most likely explanation?","options":["Chronic myeloid leukaemia","Leukaemoid reaction","Chronic lymphocytic leukaemia","Acute myeloid leukaemia"],"correct":1,"explanation":"A very high neutrophil count with toxic changes in a patient with severe infection is a leukaemoid (reactive) reaction. CML is tempting, but it shows a myelocyte peak, basophilia and splenomegaly and carries BCR-ABL1."},
      {"section":"Haematology and Immunohaematology","topic":"Coagulation Sample Quality","stem":"A blue-top (3.2% sodium citrate) tube for PT and APTT arrives only half filled. What should the laboratory do?","options":["Add normal plasma to restore the ratio, then test it","Reject it and ask for a new sample filled to the line","Test it and shorten the reported times by 10%","Test it and add a comment that the tube was underfilled"],"correct":1,"explanation":"The correct ratio is 9 parts blood to 1 part citrate; an underfilled tube has too much citrate for the plasma, which falsely prolongs clotting times and cannot be corrected by calculation. Adding normal plasma would change the result itself, so the sample must be recollected."},
      {"section":"Microbiology","topic":"CSF Specimen Handling","stem":"A CSF specimen for bacterial culture arrives at the laboratory but cannot be plated for 2 hours. How should it be kept meanwhile?","options":["In a freezer at –20 °C","In a refrigerator at 2–8 °C","In 10% formalin","In an incubator at 35–37 °C"],"correct":3,"explanation":"Neisseria meningitidis and Haemophilus influenzae die quickly in the cold, so CSF for culture must never be refrigerated. Refrigeration is correct for many other specimens, which is why it is a common mistake."},
      {"section":"Microbiology","topic":"Urethral Discharge Gram Stain","stem":"A Gram stain of urethral pus from a man with discharge shows many pus cells containing Gram-negative diplococci. What is the most likely cause?","options":["Streptococcus pneumoniae","Neisseria gonorrhoeae","Chlamydia trachomatis","Trichomonas vaginalis"],"correct":1,"explanation":"Intracellular Gram-negative kidney-shaped diplococci in pus cells from a man are diagnostic of gonorrhoea. Chlamydia also causes urethritis but cannot be seen on a Gram stain."},
      {"section":"Microbiology","topic":"Thick Blood Film","stem":"A 5-year-old child has fever at a health centre. Malaria with a low parasite count is suspected. Which preparation gives the best chance of finding parasites?","options":["A Giemsa-stained thin blood film","A Gram-stained blood smear","A wet mount of fresh blood in saline","A Giemsa-stained thick blood film"],"correct":3,"explanation":"The thick film examines many layers of lysed red cells, so it is far more sensitive for low parasitaemia. The thin film is used mainly to identify the species, not to detect few parasites."},
      {"section":"Microbiology","topic":"Malaria Film Fixation","stem":"A new technician fixes both the thick and the thin film on a malaria slide with methanol before Giemsa staining. What problem will this cause?","options":["The thin film will wash off during staining","Parasite chromatin will stain blue instead of red","Gametocytes will be destroyed in both films","Red cells in the thick film will not lyse, so it cannot be read properly"],"correct":3,"explanation":"The thick film must not be fixed: water in the stain should lyse (dehaemoglobinise) its red cells. Methanol is meant only for the thin film, and it is what keeps that film on the slide."},
      {"section":"Microbiology","topic":"Giemsa Buffer pH","stem":"At what pH should the buffered water used to dilute Giemsa stain for malaria films be?","options":["pH 7.2","pH 8.2","pH 6.8","pH 7.6"],"correct":0,"explanation":"WHO recommends buffered water at pH 7.2 so that parasite chromatin, cytoplasm and Schüffner's dots stain correctly. pH 6.8 is too acidic for Giemsa malaria staining and gives poor stippling."},
      {"section":"Microbiology","topic":"Parasite Density Calculation","stem":"On a thick film, 160 asexual P. falciparum parasites are counted against 200 white cells. The WBC count is not known, so 8 000/µL is assumed. What is the parasite density?","options":["1 600 parasites/µL","6 400 parasites/µL","3 200 parasites/µL","12 800 parasites/µL"],"correct":1,"explanation":"Parasites/µL = parasites counted × 8 000 ÷ WBCs counted = 160 × 8 000 ÷ 200 = 6 400. Dividing by 400 instead of 200 gives the wrong answer of 3 200."},
      {"section":"Microbiology","topic":"Plasmodium falciparum","stem":"A thin film shows many small ring forms, some red cells with two rings, rings at the edge of the cell, and crescent-shaped gametocytes. Infected red cells are not enlarged. Which species is this?","options":["Plasmodium vivax","Plasmodium falciparum","Plasmodium malariae","Plasmodium ovale"],"correct":1,"explanation":"Multiple fine rings, edge (appliqué) forms, normal-sized cells and banana-shaped gametocytes are typical of P. falciparum. P. vivax and P. ovale enlarge the red cell and show Schüffner's dots."},
      {"section":"Microbiology","topic":"Plasmodium malariae","stem":"A thin film shows normal-sized or small red cells with band-shaped trophozoites across the cell and schizonts with about 8 merozoites arranged like a rosette. Which species is this?","options":["Plasmodium vivax","Plasmodium falciparum","Plasmodium malariae","Plasmodium ovale"],"correct":2,"explanation":"Band forms and rosette schizonts in cells that are not enlarged are typical of P. malariae. P. vivax and P. ovale enlarge the red cell, and P. falciparum schizonts are rarely seen in peripheral blood."},
      {"section":"Microbiology","topic":"HRP2 RDT Persistence","stem":"A child treated for P. falciparum malaria with artemether–lumefantrine 2 weeks ago now has fever again. An HRP2-based RDT is positive but a good-quality thick film shows no parasites. What best explains the RDT result?","options":["HRP2 antigen can remain in the blood for weeks after the parasites are cleared","The RDT detects antibodies left from the earlier infection","The parasites have become resistant to artemether–lumefantrine","The RDT is detecting a new P. ovale infection"],"correct":0,"explanation":"HRP2 persists for weeks after successful treatment, so HRP2 RDTs should not be used to check treatment response; use microscopy. Malaria RDTs detect parasite antigen, not antibodies."},
      {"section":"Microbiology","topic":"RDT and Non-falciparum","stem":"A patient has P. ovale confirmed on a blood film, but an HRP2-only malaria RDT is negative. What is the most likely reason?","options":["The parasite density is too high (prozone effect)","The test was read before the control line appeared","P. ovale is shown only by the control line","HRP2 is produced only by P. falciparum"],"correct":3,"explanation":"HRP2-only RDTs detect P. falciparum alone; other species need a pan-specific antigen (pLDH or aldolase). A prozone effect occurs with very high P. falciparum densities, not with P. ovale."},
      {"section":"Microbiology","topic":"Stool Wet Mounts","stem":"Why should a saline wet mount, and not only an iodine mount, be prepared from a fresh stool?","options":["Iodine kills trophozoites, so their movement can only be seen in saline","Saline stains cyst nuclei better than iodine","Iodine dissolves helminth eggs","Saline concentrates the parasites in the stool"],"correct":0,"explanation":"Motile trophozoites are recognised in saline; iodine kills them but stains cyst nuclei and glycogen. So iodine, not saline, is better for showing cyst nuclei."},
      {"section":"Microbiology","topic":"Entamoeba histolytica","stem":"A fresh, warm, bloody-mucoid stool shows motile amoebic trophozoites containing ingested red blood cells. Which parasite is most likely?","options":["Entamoeba coli","Endolimax nana","Entamoeba histolytica","Giardia intestinalis"],"correct":2,"explanation":"Trophozoites with ingested red cells are the key sign of invasive E. histolytica (amoebic dysentery). E. coli is a harmless amoeba that does not ingest red cells."},
      {"section":"Microbiology","topic":"Giardia","stem":"A child has chronic diarrhoea with bloating. A saline mount shows pear-shaped trophozoites with two nuclei moving with a \"falling leaf\" motion. Which parasite is this?","options":["Balantidium coli","Giardia intestinalis","Chilomastix mesnili","Trichomonas hominis"],"correct":1,"explanation":"Two nuclei, a pear shape and falling-leaf motility identify Giardia. Trichomonas hominis is also pear-shaped but has one nucleus, an undulating membrane and jerky movement."},
      {"section":"Clinical Chemistry","topic":"Obstructive Jaundice Pattern","stem":"A 60-year-old man has yellow eyes, dark urine and pale stools. Which set of results best fits obstruction of the common bile duct?","options":["Conjugated bilirubin normal, ALP high, GGT normal","Unconjugated bilirubin high, ALT very high, urine bilirubin negative","Conjugated bilirubin high, ALP markedly high, urine urobilinogen absent","Unconjugated bilirubin high, ALP normal, urine urobilinogen increased"],"correct":2,"explanation":"In bile duct obstruction conjugated bilirubin backs up into blood and urine, ALP (with GGT) rises sharply, and little bilirubin reaches the gut, so urobilinogen is absent and stools are pale. High unconjugated bilirubin with increased urobilinogen is the haemolytic pattern."},
      {"section":"Clinical Chemistry","topic":"Haemolytic Jaundice Urine","stem":"A child with sickle cell disease is jaundiced during a haemolytic crisis. Which urine dipstick findings are expected?","options":["Bilirubin positive, urobilinogen increased","Bilirubin negative, urobilinogen absent","Bilirubin negative, urobilinogen increased","Bilirubin positive, urobilinogen absent"],"correct":2,"explanation":"In haemolysis the extra bilirubin is unconjugated and bound to albumin, so it does not pass into urine, while more bilirubin reaching the gut gives more urobilinogen in urine. Positive bilirubin with absent urobilinogen is the obstructive pattern."},
      {"section":"Clinical Chemistry","topic":"Raised ALP in Adolescent","stem":"A healthy 14-year-old boy has an ALP twice the adult upper limit. His GGT, bilirubin and ALT are normal. What is the most likely explanation?","options":["Liver damage caused by alcohol","Contamination of the sample with EDTA","Bone ALP released during normal growth","Early obstruction of the bile ducts"],"correct":2,"explanation":"Children and teenagers have high bone ALP from active bone growth, so adult ranges do not apply; a normal GGT shows the ALP is not from the liver. EDTA contamination would make ALP falsely low, not high, because EDTA binds the zinc and magnesium the enzyme needs."},
      {"section":"Clinical Chemistry","topic":"AST to ALT Ratio","stem":"A 48-year-old man has AST 190 U/L, ALT 80 U/L, GGT 420 U/L and a raised MCV. Which cause of liver injury is most likely?","options":["Alcoholic liver disease","Acute viral hepatitis","Gallstone blocking the bile duct","Paracetamol overdose"],"correct":0,"explanation":"An AST:ALT ratio above 2 (190/80 = 2.4) with a high GGT and macrocytosis strongly suggests alcohol. Acute viral hepatitis usually gives much higher ALT than AST, often above 10 times the upper limit."},
      {"section":"Clinical Chemistry","topic":"Gilbert Syndrome","stem":"A 22-year-old student becomes mildly jaundiced after fasting for several days. Total bilirubin is 48 µmol/L, mostly unconjugated. ALT, ALP, haemoglobin and reticulocyte count are normal. What is the most likely diagnosis?","options":["Dubin-Johnson syndrome","Haemolytic anaemia","Acute hepatitis A","Gilbert syndrome"],"correct":3,"explanation":"Gilbert syndrome is a mild, harmless reduction in bilirubin conjugation; unconjugated bilirubin rises with fasting or illness while liver enzymes and blood count stay normal. Haemolytic anaemia is unlikely with a normal haemoglobin and reticulocyte count, and Dubin-Johnson causes conjugated hyperbilirubinaemia."},
      {"section":"Clinical Chemistry","topic":"Liver Synthetic Function","stem":"A patient has acute liver failure after a paracetamol overdose. Which test shows a change in the liver's synthetic function soonest?","options":["Serum ALT activity","Serum albumin concentration","Prothrombin time (INR)","Serum GGT activity"],"correct":2,"explanation":"Several clotting factors made by the liver have half-lives of hours (factor VII about 6 hours), so the prothrombin time/INR rises within a day or two. Albumin has a half-life of about 3 weeks, so it falls late; ALT shows cell injury, not synthetic function."},
      {"section":"Clinical Chemistry","topic":"High Anion Gap Acidosis","stem":"A man has Na 138, K 4.0, Cl 100 and HCO3 10 mmol/L. Using anion gap = Na - (Cl + HCO3), with a reference of 8-16 mmol/L, which condition best fits?","options":["Prolonged vomiting","Renal tubular acidosis","Severe diarrhoea","Diabetic ketoacidosis"],"correct":3,"explanation":"Anion gap = 138 - (100 + 10) = 28 mmol/L, a high anion gap metabolic acidosis caused by unmeasured acids such as ketones. Diarrhoea and renal tubular acidosis give a normal anion gap acidosis, and vomiting gives a metabolic alkalosis."},
      {"section":"Clinical Chemistry","topic":"Normal Anion Gap Acidosis","stem":"A 2-year-old has had profuse watery diarrhoea for 4 days. Results: Na 136, Cl 114, HCO3 12 mmol/L (anion gap reference 8-16 mmol/L). What is the best interpretation?","options":["Normal anion gap metabolic acidosis from bicarbonate loss","Respiratory acidosis from slow breathing","High anion gap metabolic acidosis from lactic acid","Metabolic alkalosis from loss of gastric acid"],"correct":0,"explanation":"Anion gap = 136 - (114 + 12) = 10 mmol/L, which is normal; the low bicarbonate with high chloride shows bicarbonate lost in stool (hyperchloraemic acidosis). A high anion gap would need the gap to be above 16 mmol/L."},
      {"section":"Clinical Chemistry","topic":"Pseudohyponatraemia","stem":"A serum sample is visibly milky. Sodium on the main analyser (indirect ion-selective electrode) is 126 mmol/L, but on the blood gas analyser (direct ion-selective electrode) it is 139 mmol/L. What explains the difference?","options":["The patient has true hyponatraemia missed by the blood gas analyser","Lipids lower the plasma water fraction, falsely lowering the indirect result","Lipids carry sodium, falsely raising the direct result","Lipaemia makes red cells take up sodium in the tube"],"correct":1,"explanation":"Indirect ISE dilutes the sample and assumes plasma is about 93% water; when lipids take up part of the volume, the calculated sodium is falsely low (pseudohyponatraemia). Direct ISE measures sodium activity in plasma water without dilution, so its result is the true one."},
      {"section":"Clinical Chemistry","topic":"Albumin-Adjusted Calcium","stem":"A patient has total calcium 1.90 mmol/L and albumin 24 g/L. Using adjusted calcium = total calcium + 0.02 x (40 - albumin in g/L), what is the adjusted calcium?","options":["2.22 mmol/L","2.70 mmol/L","1.58 mmol/L","2.38 mmol/L"],"correct":0,"explanation":"Adjusted calcium = 1.90 + 0.02 x (40 - 24) = 1.90 + 0.02 x 16 = 1.90 + 0.32 = 2.22 mmol/L. Subtracting the correction gives the wrong value of 1.58 mmol/L; the low total calcium is mainly due to low albumin."},
      {"section":"Clinical Chemistry","topic":"Osmolal Gap","stem":"A confused man has Na 140, glucose 5 and urea 5 mmol/L. Measured serum osmolality is 320 mOsm/kg. Calculated osmolality = 2Na + glucose + urea, and a normal osmolal gap is below 10. Which condition is most likely?","options":["Syndrome of inappropriate ADH secretion","Diabetic ketoacidosis","Diabetes insipidus","Methanol poisoning"],"correct":3,"explanation":"Calculated osmolality = 2 x 140 + 5 + 5 = 290; osmolal gap = 320 - 290 = 30 mOsm/kg, showing an unmeasured osmotically active substance such as methanol, ethylene glycol or ethanol. DKA would show high glucose, and diabetes insipidus raises sodium rather than creating a gap."},
      {"section":"Clinical Chemistry","topic":"Pseudohyperkalaemia Thrombocytosis","stem":"A patient with a platelet count of 1,200 x 10⁹/L has a serum potassium of 6.4 mmol/L. There is no haemolysis and the ECG is normal. Which sample best checks whether the high potassium is real?","options":["Serum left to clot for a longer time","A random urine sample for potassium","EDTA plasma from a purple-top tube","Lithium heparin plasma, separated promptly"],"correct":3,"explanation":"Platelets release potassium while blood clots, so very high platelet counts give falsely high serum potassium; plasma from a heparin tube avoids clotting and shows the true value. EDTA tubes contain potassium EDTA and are never used for potassium."},
      {"section":"Histopathology and Laboratory Management","topic":"Routine Section Thickness","stem":"What is the usual thickness for routine paraffin sections to be stained with H&E?","options":["0.5-1 micrometre","3-5 micrometres","10-15 micrometres","20-30 micrometres"],"correct":1,"explanation":"Routine paraffin sections are cut at about 3-5 micrometres so cells lie in a single layer with clear nuclear detail. 0.5-1 micrometre is the semithin range for resin sections, not paraffin."},
      {"section":"Histopathology and Laboratory Management","topic":"Floating Out Sections","stem":"When a ribbon is placed on the flotation water bath, the sections spread too much and break apart. What is the most likely cause?","options":["The sections were cut too thick","The water is too hot, near the melting point of the wax","The slides were not cleaned with alcohol","The water is too cool for the wax"],"correct":1,"explanation":"The water bath should be several degrees below the wax melting point; if it is too hot the wax softens and the sections over-expand and disintegrate. Water that is too cool causes the opposite problem: sections stay folded and wrinkled."},
      {"section":"Histopathology and Laboratory Management","topic":"Crumbling Paraffin Block","stem":"While cutting a block, the centre of the tissue crumbles and falls out, leaving a hole. The edges cut well. What is the most likely cause?","options":["The block was chilled before cutting","Incomplete dehydration and wax infiltration of the tissue centre","The tissue was over-stained with eosin","The blade angle is too steep"],"correct":1,"explanation":"If the centre of a thick or fatty piece is not fully dehydrated, cleared and infiltrated, it is not supported by wax and crumbles; the tissue should be reprocessed. Chilling the block is normal practice and helps cutting rather than causing holes."},
      {"section":"Histopathology and Laboratory Management","topic":"Haematoxylin Mordant","stem":"What is the role of potassium alum (aluminium salt) in Harris or Mayer haematoxylin?","options":["It removes excess dye from the cytoplasm","It oxidises haematoxylin into haematein","It is a preservative that stops mould growth","It is the mordant that links the dye to nuclear chromatin"],"correct":3,"explanation":"The aluminium mordant combines with haematein to form a positively charged dye-lake that binds the phosphate groups of nuclear DNA. Oxidation to haematein is done by a separate agent such as sodium iodate or mercuric oxide."},
      {"section":"Histopathology and Laboratory Management","topic":"Blueing in H&E","stem":"After haematoxylin and acid alcohol, the nuclei look reddish-purple and poorly defined. The eosin has not yet been applied. Which step is needed next?","options":["Blueing in an alkaline solution such as Scott's tap water substitute","Dehydration in absolute alcohol","A second rinse in acid alcohol","Clearing in xylene"],"correct":0,"explanation":"Alum haematoxylin is red in acid; an alkaline solution (Scott's or alkaline tap water) turns it into the insoluble blue colour of well-stained nuclei. More acid alcohol would remove even more haematoxylin and make nuclei paler."},
      {"section":"Histopathology and Laboratory Management","topic":"Pale Nuclear Staining","stem":"An H&E slide shows good pink eosin staining but very pale nuclei. The haematoxylin is freshly made. What is the most likely cause?","options":["The slides stayed too long in acid alcohol","The slides stayed too long in Scott's tap water substitute","The sections were cut too thick","The eosin was too concentrated"],"correct":0,"explanation":"In regressive staining, acid alcohol removes haematoxylin; leaving slides in it too long over-differentiates and pales the nuclei. Longer blueing does not remove haematoxylin, and thick sections would make nuclei darker, not paler."},
      {"section":"Histopathology and Laboratory Management","topic":"Haematoxylin Precipitate","stem":"Many H&E slides show dark blue-black granular deposits lying on top of the sections. The haematoxylin has a shiny film on its surface. What is the best corrective action?","options":["Shorten the blueing step","Extend the time in eosin","Cut the sections thinner","Filter the haematoxylin before use"],"correct":3,"explanation":"Oxidised haematoxylin forms a metallic surface film and precipitate that settles on slides; filtering the stain before use removes it. Changing eosin or blueing times does not affect a haematoxylin precipitate."},
      {"section":"Histopathology and Laboratory Management","topic":"PAS With Diastase","stem":"In a liver biopsy, PAS stains many magenta granules in the hepatocytes. On a serial section treated with diastase first, the granules are gone. What is the material?","options":["Neutral mucin","Fungal cell walls","Glycogen","Alpha-1-antitrypsin globules"],"correct":2,"explanation":"Diastase digests glycogen, so PAS-positive material that disappears after diastase is glycogen. Alpha-1-antitrypsin globules are tempting because they are PAS-positive, but they resist diastase."},
      {"section":"Histopathology and Laboratory Management","topic":"Congo Red for Amyloid","stem":"A rectal biopsy is sent to look for amyloid. The Congo red stain shows pink-red deposits. What finding confirms amyloid?","options":["Magenta staining that is removed by diastase","Apple-green birefringence under polarised light","Black deposits after silver impregnation","Blue granules after Perls' reaction"],"correct":1,"explanation":"Amyloid stained with Congo red gives characteristic apple-green birefringence in polarised light, which confirms it. Red colour alone is not specific, because other proteins can take up Congo red."},
      {"section":"Histopathology and Laboratory Management","topic":"Perls Stain for Iron","stem":"A pathologist wants to see haemosiderin (stored iron) in a liver biopsy. Which stain should be done?","options":["Von Kossa","Perls' Prussian blue","Ziehl-Neelsen","Masson-Fontana"],"correct":1,"explanation":"Perls' reaction (potassium ferrocyanide in hydrochloric acid) turns ferric iron in haemosiderin bright blue. Masson-Fontana is for melanin and von Kossa for calcium deposits."},
      {"section":"Histopathology and Laboratory Management","topic":"Silver Stain for Fungi","stem":"A lung biopsy from a patient with advanced HIV is suspected to contain Pneumocystis jirovecii. Which stain best shows the cysts?","options":["Van Gieson","Grocott methenamine silver","Ziehl-Neelsen","Perls' Prussian blue"],"correct":1,"explanation":"Grocott methenamine silver stains the walls of Pneumocystis cysts and other fungi black against a green background. Ziehl-Neelsen is for acid-fast bacilli such as M. tuberculosis, not fungi."},
      {"section":"Histopathology and Laboratory Management","topic":"Pap Smear Fixation","stem":"A nurse at a district hospital spreads a conventional cervical smear on a slide. What should she do next?","options":["Fix the slide in 10% formalin","Let the smear dry in air for 10 minutes, then fix it","Put the slide at once into 95% ethanol while the smear is still wet","Pass the slide through a flame to heat-fix it"],"correct":2,"explanation":"Pap smears need immediate wet fixation in 95% ethanol (or a spray fixative) to keep nuclear detail for the Papanicolaou stain. Air-drying first causes swollen, pale, smudged nuclei that can hide or mimic abnormalities."},
    ],
  },
  {
    country: 'RW', category: 'licensing-exams',
    profession: {"slug":"rahpc-biomedical-laboratory-sciences-licensing-exam","name":"Biomedical Laboratory Sciences Licensing Exam (RAHPC)"},
    slug: "rahpc-biomedical-laboratory-sciences-mock-exam-3",
    title: "Biomedical Laboratory Sciences Licensing Exam (RAHPC) — Mock Exam 3",
    summary: "Haematology and Immunohaematology; Microbiology; Clinical Chemistry; Histopathology and Laboratory Management.",
    free: false, difficulty: 'STANDARD', minutes: 60,
    instructions: ["50 multiple-choice questions, one best answer each, 60 minutes.","RAHPC does not publish the number of questions or the time of its registry exam; these mocks cover its published thematic areas."],
    sections: [{"name":"Haematology and Immunohaematology"},{"name":"Microbiology"},{"name":"Clinical Chemistry"},{"name":"Histopathology and Laboratory Management"}],
    questions: [
      {"section":"Haematology and Immunohaematology","topic":"INR Calculation","stem":"A patient on warfarin has a PT of 30 seconds. The laboratory's mean normal PT is 12 seconds and the thromboplastin ISI is 1.0. What is the INR?","options":["18","2.5","3.0","0.4"],"correct":1,"explanation":"INR = (patient PT ÷ mean normal PT)^ISI = (30 ÷ 12)^1.0 = 2.5. The answer 0.4 comes from dividing the wrong way (12 ÷ 30), and 18 is simply the difference in seconds."},
      {"section":"Haematology and Immunohaematology","topic":"Mixing Studies","stem":"A patient's APTT is 62 s (normal range 28–38 s). After a 1:1 mix with normal pooled plasma, the APTT is 34 s at once and stays normal after 2 hours' incubation at 37 °C. What does this suggest?","options":["A clotting factor deficiency","A lupus anticoagulant","Heparin in the sample","An acquired factor VIII inhibitor"],"correct":0,"explanation":"Normal plasma supplies the missing factor, so full correction that holds after incubation means a factor deficiency. An acquired factor VIII inhibitor may correct at first but becomes prolonged again after incubation at 37 °C, and lupus anticoagulant or heparin do not correct."},
      {"section":"Haematology and Immunohaematology","topic":"Haemophilia Screening","stem":"A 6-year-old boy has repeated painful swollen knees after minor falls. His maternal uncle had the same problem. Platelets and PT are normal; the APTT is prolonged. Which factor is most likely deficient?","options":["Factor VIII","Factor VII","Fibrinogen","Factor XII"],"correct":0,"explanation":"Joint bleeds in a boy with an affected maternal uncle (X-linked) and an isolated prolonged APTT fit haemophilia A, factor VIII deficiency. Factor XII deficiency also prolongs the APTT but does not cause bleeding; factor VII deficiency prolongs the PT."},
      {"section":"Haematology and Immunohaematology","topic":"PT and APTT Pathways","stem":"A patient has a prolonged PT but a normal APTT. Deficiency of which single clotting factor best explains this pattern?","options":["Factor IX","Factor VII","Factor VIII","Factor XI"],"correct":1,"explanation":"Factor VII is measured by the PT (extrinsic pathway) but not by the APTT. Factors VIII, IX and XI are in the intrinsic pathway, so their deficiency prolongs the APTT with a normal PT."},
      {"section":"Haematology and Immunohaematology","topic":"Heparin Contamination","stem":"A sample taken through a central line has an APTT above 120 s and a very prolonged thrombin time, but a normal reptilase time. The patient is not bleeding. What is the most likely cause?","options":["Dysfibrinogenaemia","Heparin contamination of the sample","Disseminated intravascular coagulation","Low fibrinogen"],"correct":1,"explanation":"Heparin prolongs the thrombin time, but reptilase (a snake venom enzyme) is not inhibited by heparin, so a normal reptilase time points to heparin; a new sample should be taken from a peripheral vein. Low or abnormal fibrinogen prolongs both the thrombin time and the reptilase time."},
      {"section":"Haematology and Immunohaematology","topic":"Disseminated Intravascular Coagulation","stem":"One hour after a delivery complicated by placental abruption, a woman at a district hospital is bleeding from her IV sites. Results: platelets 45 × 10^9/L, PT and APTT prolonged, fibrinogen 0.9 g/L, D-dimer very high. What is the most likely diagnosis?","options":["Immune thrombocytopenia","Haemophilia A carrier state","Vitamin K deficiency","Disseminated intravascular coagulation"],"correct":3,"explanation":"Low platelets, prolonged PT and APTT, low fibrinogen and a high D-dimer after placental abruption show consumption of clotting factors with fibrinolysis, which is DIC. ITP lowers the platelets only, and vitamin K deficiency mainly prolongs the PT with normal fibrinogen and platelets."},
      {"section":"Haematology and Immunohaematology","topic":"ABO and RhD Interpretation","stem":"Tube grouping results: patient's cells with anti-A 4+, anti-B 0, anti-D 3+. Patient's plasma with A1 cells 0, B cells 4+. What is the blood group?","options":["AB RhD positive","B RhD positive","A RhD negative","A RhD positive"],"correct":3,"explanation":"The cells carry A antigen and D antigen, and the plasma contains anti-B only, so forward and reverse groups agree on group A RhD positive. Group A RhD negative is wrong because the cells react 3+ with anti-D."},
      {"section":"Haematology and Immunohaematology","topic":"Neonatal ABO Grouping","stem":"A 6-week-old baby's red cells do not react with anti-A or anti-B, and the baby's plasma does not react with A1 or B cells. What is the best interpretation?","options":["Reagent A1 and B cells have deteriorated","Group AB with weak A and B antigens","Group O; anti-A and anti-B are not yet made at this age","Bombay phenotype with absent H antigen"],"correct":2,"explanation":"Babies usually do not make their own anti-A and anti-B until about 3–6 months, so neonates are grouped by the forward (cell) group only. The Bombay phenotype is extremely rare and is shown by a negative anti-H lectin test; missing reverse reactions are normal at this age."},
      {"section":"Haematology and Immunohaematology","topic":"ABO Grouping Discrepancy","stem":"A 65-year-old man with multiple myeloma groups as A on forward grouping, but his plasma agglutinates A1 cells, B cells and group O screening cells. Under the microscope the 'agglutinates' look like stacks of coins. What should be done to resolve the reverse group?","options":["Treat his red cells with papain","Repeat the reverse group at 4 °C","Report him as group O","Use the saline replacement technique"],"correct":3,"explanation":"High paraprotein causes rouleaux, which mimic agglutination; replacing the plasma with saline disperses rouleaux but not true agglutinates. Testing at 4 °C would enhance cold antibodies and make the problem worse."},
      {"section":"Haematology and Immunohaematology","topic":"Bombay Phenotype","stem":"A woman's red cells do not react with anti-A, anti-B or anti-H lectin. Her plasma strongly agglutinates A1, B and group O cells at room temperature and at 37 °C. She needs a red cell transfusion. Which units are compatible?","options":["Group O RhD negative units","Group AB units","Washed group O units","Units from Bombay (Oh) phenotype donors"],"correct":3,"explanation":"She has the Bombay phenotype: her cells lack H antigen and her plasma contains anti-H as well as anti-A and anti-B, so only Bombay blood is compatible. Group O cells are rich in H antigen and would be destroyed by her anti-H, even if washed."},
      {"section":"Haematology and Immunohaematology","topic":"ABO Subgroups","stem":"A patient's red cells react 4+ with anti-A and do not react with anti-B. The plasma reacts 4+ with B cells and 1+ with A1 cells at room temperature. The red cells do not react with Dolichos biflorus (anti-A1) lectin. What is the most likely explanation?","options":["Rouleaux from raised plasma proteins","Bombay phenotype","A2 subgroup with anti-A1 in the plasma","Acquired B antigen"],"correct":2,"explanation":"Red cells that react with anti-A but not with anti-A1 lectin are A2; some A2 people make anti-A1, which reacts weakly with A1 cells. Acquired B would give a weak reaction with anti-B, and rouleaux would make the plasma react with every reagent cell, including group O cells."},
      {"section":"Haematology and Immunohaematology","topic":"Weak D Testing","stem":"A blood donor's red cells give no reaction with anti-D at immediate spin. Before the unit is labelled RhD negative, what further test should be done?","options":["Test the donor's plasma for anti-D","Test for weak D by the indirect antiglobulin technique","Repeat the anti-D test at room temperature for 1 hour","Perform a direct antiglobulin test on the donor"],"correct":1,"explanation":"Weak D cells may react only after incubation with anti-D at 37 °C and addition of AHG (indirect antiglobulin technique); a weak D unit labelled negative could immunise a D-negative recipient. A DAT detects antibody already on the cells in the body, not a weak antigen."},
      {"section":"Haematology and Immunohaematology","topic":"Plasma ABO Compatibility","stem":"A bleeding patient urgently needs fresh frozen plasma before his blood group is known. Which ABO group of plasma is safe for any recipient?","options":["Group AB","Group A","Group O","Group B"],"correct":0,"explanation":"Group AB plasma contains neither anti-A nor anti-B, so it cannot damage any recipient's red cells. Group O is the universal group for red cells, but group O plasma contains both anti-A and anti-B."},
      {"section":"Microbiology","topic":"Kato-Katz Egg Count","stem":"A Kato–Katz smear made with a 41.7 mg template shows 15 Schistosoma mansoni eggs. What is the eggs per gram (EPG) of stool?","options":["180 EPG","360 EPG","625 EPG","1 500 EPG"],"correct":1,"explanation":"1 g ÷ 41.7 mg = 24, so EPG = 15 × 24 = 360. Multiplying by 41.7 instead (15 × 41.7 ≈ 625) uses the template weight wrongly."},
      {"section":"Microbiology","topic":"Schistosoma haematobium","stem":"Which urine specimen is best for detecting Schistosoma haematobium eggs?","options":["Midstream urine collected at midnight","Terminal urine collected around midday (10:00–14:00)","Catheter urine collected early in the morning","First urine passed on waking in the morning"],"correct":1,"explanation":"Egg output is highest around midday and eggs collect in the last part of the stream, so terminal midday urine is best. Early-morning urine is right for many other tests but not for S. haematobium."},
      {"section":"Microbiology","topic":"Strongyloides","stem":"A fresh stool from an HIV-positive man with diarrhoea shows motile rhabditiform larvae but no eggs. Which parasite is most likely?","options":["Hookworm","Ascaris lumbricoides","Trichuris trichiura","Strongyloides stercoralis"],"correct":3,"explanation":"Strongyloides eggs hatch in the gut, so larvae (not eggs) are passed in fresh stool. Hookworm larvae appear only when stool has been left standing for many hours; fresh stool shows hookworm eggs."},
      {"section":"Microbiology","topic":"HIV Serial Testing","stem":"In a serial HIV rapid testing algorithm, which property is most important for the first test (A1)?","options":["Highest sensitivity, so very few infections are missed","Ability to tell HIV-1 from HIV-2","Lowest cost per test","Highest specificity, so false positives are avoided"],"correct":0,"explanation":"The first test must be the most sensitive so that a non-reactive result can be trusted as negative. High specificity matters for the later tests that confirm a reactive A1."},
      {"section":"Microbiology","topic":"HIV Non-reactive A1","stem":"A client's first HIV rapid test (A1) is non-reactive. She reports no recent risk exposure. What should be done?","options":["Send a sample for HIV viral load","Run the second test (A2) to confirm the negative result","Report inconclusive and retest after 14 days","Report HIV-negative without further testing"],"correct":3,"explanation":"In a serial algorithm a non-reactive A1 is reported negative; A2 is used only after a reactive A1. Running A2 on a negative wastes kits and adds no accuracy."},
      {"section":"Microbiology","topic":"HIV Discordant Results","stem":"During HIV testing, A1 is reactive and A2 is non-reactive. What is the correct action?","options":["Give no final result; manage it as discordant following the national algorithm","Report HIV-negative because A2 is the more specific test","Repeat A2 several times and report the majority result","Report HIV-positive because A1 is the most sensitive test"],"correct":0,"explanation":"A reactive A1 with a non-reactive A2 is discordant and cannot be reported as positive or negative; the national algorithm says how to resolve it. Reporting positive on A1 alone risks a false-positive diagnosis."},
      {"section":"Microbiology","topic":"HIV Retest Before ART","stem":"Why does WHO recommend retesting a person newly diagnosed HIV-positive before starting ART?","options":["To detect infection still in the window period","To measure the baseline viral load","To find out whether the infection is recent","To rule out misdiagnosis from technical or clerical errors"],"correct":3,"explanation":"Retesting on a new specimen catches errors such as sample mix-ups before lifelong treatment starts. The window period is a problem for negative results, not positive ones."},
      {"section":"Microbiology","topic":"Infant HIV Diagnosis","stem":"A 9-month-old baby of an HIV-positive mother has a reactive HIV rapid antibody test. What test is needed to diagnose HIV infection in the baby?","options":["A second rapid antibody test of another brand","An HIV antibody ELISA","An HIV nucleic acid test (e.g. DNA PCR on dried blood spot)","A CD4 count"],"correct":2,"explanation":"Maternal HIV antibodies cross the placenta and can last up to 18 months, so antibody tests cannot diagnose infant infection. A virological (nucleic acid) test is needed."},
      {"section":"Microbiology","topic":"HIV Markers Timeline","stem":"After HIV infection, which marker becomes detectable in the blood first?","options":["p24 antigen","HIV IgM antibody","HIV RNA","HIV IgG antibody"],"correct":2,"explanation":"HIV RNA appears first (about 10 days), then p24 antigen, then antibodies. p24 comes before antibody, which is why 4th-generation tests shorten the window, but it still follows RNA."},
      {"section":"Microbiology","topic":"Acute Hepatitis B","stem":"A man has had jaundice for 2 weeks. Results: HBsAg positive, IgM anti-HBc positive, anti-HBs negative. What is the interpretation?","options":["Chronic hepatitis B infection","Immunity from vaccination","Acute hepatitis B infection","Past infection with immunity"],"correct":2,"explanation":"HBsAg with IgM anti-HBc means recent (acute) infection. Chronic infection is shown by HBsAg persisting over 6 months, usually with IgG (not IgM) anti-HBc."},
      {"section":"Microbiology","topic":"HBV Vaccine Immunity","stem":"A health worker's results: HBsAg negative, total anti-HBc negative, anti-HBs positive (>10 mIU/mL). What does this mean?","options":["Window period of acute infection","Immunity after natural infection","Immunity from hepatitis B vaccination","Chronic hepatitis B carrier"],"correct":2,"explanation":"Anti-HBs alone, without anti-HBc, comes from vaccination. Immunity after natural infection shows both anti-HBs and anti-HBc."},
      {"section":"Microbiology","topic":"Chronic Hepatitis B","stem":"A woman tests HBsAg positive at antenatal care and is still HBsAg positive 7 months later. What does this indicate?","options":["Resolved hepatitis B infection","Chronic hepatitis B infection","Acute hepatitis B infection","A response to hepatitis B vaccine"],"correct":1,"explanation":"HBsAg that persists for more than 6 months defines chronic infection. In acute infection that resolves, HBsAg is usually lost within 6 months."},
      {"section":"Microbiology","topic":"Hepatitis C Confirmation","stem":"A client's anti-HCV rapid test is reactive. Which test confirms current (viraemic) HCV infection?","options":["HBsAg test","HCV RNA (nucleic acid test)","A repeat anti-HCV antibody test","Serum ALT"],"correct":1,"explanation":"Anti-HCV stays positive after the infection has cleared, so HCV RNA (or core antigen) is needed to show current infection. A second antibody test cannot tell past from current infection."},
      {"section":"Clinical Chemistry","topic":"Friedewald LDL Calculation","stem":"A fasting lipid profile shows total cholesterol 6.0 mmol/L, HDL cholesterol 1.2 mmol/L and triglycerides 2.2 mmol/L. Using the Friedewald equation in mmol/L, what is the LDL cholesterol?","options":["3.8 mmol/L","2.6 mmol/L","4.4 mmol/L","4.8 mmol/L"],"correct":0,"explanation":"Friedewald (mmol/L): LDL = TC - HDL - TG/2.2 = 6.0 - 1.2 - (2.2/2.2) = 6.0 - 1.2 - 1.0 = 3.8 mmol/L. Dividing TG by 5 (the mg/dL factor) gives 4.4, and subtracting the full TG gives 2.6."},
      {"section":"Clinical Chemistry","topic":"Friedewald Limitation","stem":"A fasting sample has total cholesterol 7.1 mmol/L, HDL 0.9 mmol/L and triglycerides 6.2 mmol/L. The doctor asks for LDL cholesterol. What should the laboratory do?","options":["Calculate LDL with the Friedewald equation as usual","Ask for a non-fasting sample and calculate again","Measure LDL by a direct method instead of calculating it","Dilute the sample 1 in 2, then use the Friedewald equation"],"correct":2,"explanation":"The Friedewald equation is not valid when triglycerides are above 4.5 mmol/L, because the TG/2.2 estimate of VLDL cholesterol becomes inaccurate. Diluting the sample does not change the TG:cholesterol ratio, and a non-fasting sample would make triglycerides even higher."},
      {"section":"Clinical Chemistry","topic":"Effect of a Fatty Meal","stem":"A patient forgot to fast and ate a fatty meal 2 hours before a lipid profile. Which result is most affected?","options":["HDL cholesterol","Directly measured LDL cholesterol","Triglycerides","Total cholesterol"],"correct":2,"explanation":"After a meal, chylomicrons rich in triglyceride enter the blood, so triglycerides rise clearly for several hours. Total, HDL and directly measured LDL cholesterol change only a little after a single meal."},
      {"section":"Clinical Chemistry","topic":"Refrigerator Test Lipoproteins","stem":"A lipaemic serum is left upright overnight at 4 °C. Next morning there is a creamy layer on top and the serum below is clear. Which lipoprotein is increased?","options":["HDL","LDL","VLDL","Chylomicrons"],"correct":3,"explanation":"Chylomicrons are the least dense lipoproteins and float to form a creamy top layer on standing. Raised VLDL makes the whole sample evenly turbid without a cream layer, while LDL and HDL do not make serum cloudy."},
      {"section":"Clinical Chemistry","topic":"Enzymatic Cholesterol Method","stem":"In the enzymatic (CHOD-PAP) method for total cholesterol, which enzyme must act first so that cholesterol esters are included in the result?","options":["Cholesterol oxidase","Peroxidase","Lipoprotein lipase","Cholesterol esterase"],"correct":3,"explanation":"Cholesterol esterase first splits cholesterol esters into free cholesterol; cholesterol oxidase then oxidises free cholesterol, producing hydrogen peroxide that peroxidase uses to form a coloured dye. Without the esterase, only free cholesterol (about 30% of the total) would be measured."},
      {"section":"Clinical Chemistry","topic":"Troponin Decision Limit","stem":"According to the universal definition of myocardial infarction, a cardiac troponin result is called raised when it is above which limit?","options":["The 99th percentile upper reference limit of a healthy population","The mean plus two standard deviations of hospital patients","Twice the upper limit of the laboratory reference interval","The 97.5th percentile upper reference limit of a healthy population"],"correct":0,"explanation":"The Fourth Universal Definition of MI defines myocardial injury as a troponin above the 99th percentile upper reference limit of healthy people. The 97.5th percentile is the usual upper end of a 95% reference interval, but it is not used for troponin."},
      {"section":"Clinical Chemistry","topic":"Late Presentation Chest Pain","stem":"A 62-year-old man arrives at the district hospital 5 days after severe chest pain. Which cardiac marker is most likely to still be raised if he had a myocardial infarction?","options":["Myoglobin","CK-MB","Cardiac troponin","Total CK"],"correct":2,"explanation":"Cardiac troponin stays raised for about 7-14 days after an MI, so it can detect a late infarct. CK-MB and total CK usually return to normal in 2-3 days, and myoglobin within about 24 hours."},
      {"section":"Clinical Chemistry","topic":"Early Troponin Sampling","stem":"A 55-year-old woman comes in 1 hour after chest pain began. Her first high-sensitivity troponin is below the 99th percentile. What is the best next laboratory step?","options":["Rule out myocardial infarction on this one result","Repeat troponin after the interval set in the hospital protocol","Measure total CK because it rises earlier than troponin","Measure LDH because it is more specific for heart muscle"],"correct":1,"explanation":"Troponin may not yet have risen so soon after symptom onset; MI is ruled in or out by serial troponin samples showing a rise and/or fall. Total CK rises no earlier than troponin and is much less specific for heart muscle."},
      {"section":"Clinical Chemistry","topic":"Troponin in Kidney Failure","stem":"A patient on haemodialysis has no chest pain. Troponin T is slightly above the 99th percentile and is unchanged on a repeat sample 3 hours later. What is the best interpretation?","options":["Skeletal muscle damage from the dialysis needles","Laboratory error, because dialysis removes all troponin","Chronic myocardial injury, common in kidney failure, not an acute MI","Acute myocardial infarction needing urgent treatment"],"correct":2,"explanation":"Many patients with kidney failure have a stable, mildly raised troponin; without a rise or fall and without symptoms of ischaemia, this is chronic myocardial injury, not acute MI. Acute MI needs a dynamic change in troponin plus clinical evidence of ischaemia."},
      {"section":"Clinical Chemistry","topic":"Heart Failure Marker","stem":"A 72-year-old woman is breathless with swollen ankles. Which blood test best helps to rule out heart failure?","options":["Cardiac troponin I","CK-MB","NT-proBNP","D-dimer"],"correct":2,"explanation":"Natriuretic peptides (BNP or NT-proBNP) are released when heart muscle is stretched, and a normal level makes heart failure unlikely. Troponin and CK-MB detect heart muscle injury, and D-dimer is used to help rule out thrombosis."},
      {"section":"Clinical Chemistry","topic":"Reducing Sugars in Urine","stem":"A 3-week-old baby has jaundice, vomiting and poor feeding. The urine Benedict test is positive, but the dipstick glucose is negative. What does the urine most likely contain?","options":["Glucose below the dipstick detection limit","Ketone bodies from poor feeding","A non-glucose reducing sugar such as galactose","Sucrose from sweetened feeds"],"correct":2,"explanation":"The dipstick uses glucose oxidase, which reacts only with glucose, while Benedict reagent detects any reducing sugar; this pattern suggests galactose, as in galactosaemia. Sucrose is not a reducing sugar, so it would not give a positive Benedict test."},
      {"section":"Clinical Chemistry","topic":"Urine Ketone Test Limitation","stem":"A patient with severe diabetic ketoacidosis has only a \"trace\" urine ketone result on a nitroprusside dipstick. What is the most likely reason?","options":["Ketones only appear in urine after 48 hours","The test does not detect beta-hydroxybutyrate, the main ketone in DKA","High urine glucose blocks the nitroprusside reaction","Ketones are not filtered by the kidney in DKA"],"correct":1,"explanation":"Sodium nitroprusside reacts with acetoacetate (and weakly with acetone) but not with beta-hydroxybutyrate, which is the main ketone in severe DKA. Blood beta-hydroxybutyrate measurement is more reliable in this situation."},
      {"section":"Histopathology and Laboratory Management","topic":"Papanicolaou Stain Components","stem":"In the Papanicolaou stain, which component stains keratinised squamous cells orange?","options":["Bismarck brown","Orange G (OG-6)","Harris haematoxylin","Light green in EA"],"correct":1,"explanation":"Orange G (OG-6) stains keratin, so keratinised and mature superficial cells appear orange. Light green, part of the EA counterstain, stains the cytoplasm of less mature (intermediate and parabasal) cells blue-green."},
      {"section":"Histopathology and Laboratory Management","topic":"Koilocytes on Pap Smear","stem":"A cervical smear shows superficial squamous cells with a clear halo around enlarged, dark, wrinkled nuclei, and some binucleate cells. The affected cells are mature, with plenty of cytoplasm. What is the Bethesda category?","options":["Negative for intraepithelial lesion or malignancy (NILM)","Low-grade squamous intraepithelial lesion (LSIL)","Atypical squamous cells of undetermined significance (ASC-US)","High-grade squamous intraepithelial lesion (HSIL)"],"correct":1,"explanation":"These are koilocytes, the cytopathic effect of HPV, which Bethesda reports as LSIL. HSIL involves smaller, immature cells with a much higher nuclear-to-cytoplasmic ratio, which is not described here."},
      {"section":"Histopathology and Laboratory Management","topic":"Clue Cells","stem":"A cervical smear has no abnormal squamous cells. Many squamous cells are covered by small coccobacilli that blur the cell borders, and lactobacilli are scarce. How should this be reported?","options":["Atypical squamous cells of undetermined significance","Trichomonas vaginalis infection","Fungal organisms consistent with Candida","Shift in vaginal flora suggestive of bacterial vaginosis"],"correct":3,"explanation":"Squamous cells covered by coccobacilli are \"clue cells\"; with few lactobacilli, Bethesda reports this as a shift in flora suggestive of bacterial vaginosis, under NILM. Trichomonas appears as pear-shaped organisms with a nucleus, not as a coating of small bacteria."},
      {"section":"Histopathology and Laboratory Management","topic":"Transformation Zone Component","stem":"A conventional Pap smear has plenty of well-preserved squamous cells, but no endocervical or squamous metaplastic cells. How is its adequacy reported?","options":["Satisfactory, and the woman can skip her next screening","Unsatisfactory for evaluation; the smear must be rejected","Unsatisfactory unless the woman is pregnant","Satisfactory for evaluation, with a note that the transformation zone component is absent"],"correct":3,"explanation":"In Bethesda, absence of the transformation zone component is a quality indicator only; the smear is still satisfactory if there are enough squamous cells. Calling it unsatisfactory is a common mistake that leads to unnecessary repeat smears."},
      {"section":"Histopathology and Laboratory Management","topic":"Meaning of ASC-H","stem":"A Pap smear report says \"ASC-H\". What does this mean?","options":["Atypical squamous cells due to HPV infection","Atypical squamous cells, cannot exclude a high-grade lesion","Atypical squamous cells of undetermined significance","Atypical squamous cells with haemorrhage"],"correct":1,"explanation":"ASC-H means atypical squamous cells for which HSIL cannot be excluded, so it carries a higher risk than ASC-US and needs colposcopy. ASC-US is a separate, lower-risk category."},
      {"section":"Histopathology and Laboratory Management","topic":"Unsatisfactory Pap Smear","stem":"On a cervical smear, heavy blood obscures about 80% of the squamous cells. No abnormal cells are seen in the visible areas. How should adequacy be reported?","options":["Satisfactory, but partly obscured by blood","Satisfactory; negative for intraepithelial lesion","Unsatisfactory for evaluation","Atypical squamous cells of undetermined significance"],"correct":2,"explanation":"In Bethesda, a smear with more than 75% of squamous cells obscured is unsatisfactory, as long as no abnormal cells are seen. \"Satisfactory but partly obscured\" is used only when 50-75% is obscured."},
      {"section":"Histopathology and Laboratory Management","topic":"Frozen Section Specimen","stem":"A surgeon at a referral hospital wants an intraoperative frozen section on a breast lump. How should the specimen be sent to the lab?","options":["Soaked in saline for an hour before sending","In 10% neutral buffered formalin","In 70% alcohol to stop autolysis","Fresh and unfixed, delivered to the lab at once"],"correct":3,"explanation":"Frozen sections are cut from fresh, unfixed tissue that arrives without delay; fixation would ruin the frozen section and delay the result. Long soaking in saline causes swelling and artefacts, so it is also wrong."},
      {"section":"Histopathology and Laboratory Management","topic":"Ice Crystal Artefact","stem":"Frozen sections of a lymph node show many small holes and a \"Swiss cheese\" look in the tissue. How can this artefact best be prevented?","options":["Thaw and refreeze the block before cutting","Freeze the tissue slowly in a -20 degree C freezer","Freeze the tissue rapidly, e.g. in isopentane cooled by liquid nitrogen","Cut the sections at room temperature"],"correct":2,"explanation":"Slow freezing lets large ice crystals grow and leave holes; snap-freezing (for example in isopentane cooled by liquid nitrogen) makes crystals too small to see. Slow freezing in an ordinary freezer is the cause of the problem, not the cure."},
      {"section":"Histopathology and Laboratory Management","topic":"Cryostat Temperature for Fat","stem":"A fatty breast specimen smears and will not cut on the cryostat, while other tissues cut well at the same setting. What should the technician do?","options":["Make the specimen colder by lowering the cryostat temperature","Fix the tissue in formalin for 10 minutes first","Warm the block to just below 0 degrees C","Cut much thicker sections"],"correct":0,"explanation":"Fat freezes at a lower temperature than other tissues, so fatty tissue needs a colder block (and chamber) to cut. Warming the block makes fat even softer and smearing worse."},
      {"section":"Histopathology and Laboratory Management","topic":"Direct Immunofluorescence Specimen","stem":"A skin biopsy is taken to look for immune deposits in a suspected blistering disease (pemphigus) by direct immunofluorescence. How should it be sent?","options":["In Bouin's fluid","In 10% neutral buffered formalin","In buffered glutaraldehyde","Fresh or in Michel transport medium, for frozen sections"],"correct":3,"explanation":"Direct immunofluorescence is done on frozen sections of unfixed tissue, so the biopsy is sent fresh or in Michel transport medium. Formalin fixation and paraffin processing would mask the antigens needed for the test."},
      {"section":"Histopathology and Laboratory Management","topic":"Infection Risk at Cryostat","stem":"A surgeon requests a frozen section on a lymph node from a patient with suspected tuberculosis. What is the main biosafety concern?","options":["Freezing kills TB bacilli, so normal precautions are enough","Freezing does not kill TB bacilli, so cutting can make infectious aerosols and contaminate the cryostat","The only risk is a cut from the cryostat blade","TB bacilli are only a risk after paraffin processing"],"correct":1,"explanation":"Freezing does not inactivate M. tuberculosis, and trimming and cutting fresh tissue in the cryostat can create infectious aerosols and contaminate the chamber; such requests should be avoided or the cryostat decontaminated afterwards. Believing that freezing makes tissue safe is the dangerous mistake."},
      {"section":"Histopathology and Laboratory Management","topic":"Fat Stains Need Frozen Sections","stem":"A doctor asks for an Oil Red O stain to show fat in a tissue that has already been processed into a paraffin block. What should the lab explain?","options":["The paraffin block must first be decalcified","Fat dissolves in the alcohol and xylene used in processing, so frozen sections are needed","Oil Red O works only on bone marrow smears","Fat stains need tissue fixed in Bouin's fluid"],"correct":1,"explanation":"Alcohols and xylene in routine processing dissolve most lipids, so fat stains such as Oil Red O are done on frozen sections of wet (fixed or fresh) tissue. Changing the fixative does not help if the tissue still goes through alcohol and xylene."},
    ],
  },
  {
    country: 'RW', category: 'licensing-exams',
    profession: {"slug":"rahpc-biomedical-laboratory-sciences-licensing-exam","name":"Biomedical Laboratory Sciences Licensing Exam (RAHPC)"},
    slug: "rahpc-biomedical-laboratory-sciences-mock-exam-4",
    title: "Biomedical Laboratory Sciences Licensing Exam (RAHPC) — Mock Exam 4",
    summary: "Haematology and Immunohaematology; Microbiology; Clinical Chemistry; Histopathology and Laboratory Management.",
    free: false, difficulty: 'STANDARD', minutes: 60,
    instructions: ["50 multiple-choice questions, one best answer each, 60 minutes.","RAHPC does not publish the number of questions or the time of its registry exam; these mocks cover its published thematic areas."],
    sections: [{"name":"Haematology and Immunohaematology"},{"name":"Microbiology"},{"name":"Clinical Chemistry"},{"name":"Histopathology and Laboratory Management"}],
    questions: [
      {"section":"Haematology and Immunohaematology","topic":"Fetomaternal Haemorrhage","stem":"An RhD-negative mother has just delivered an RhD-positive baby. Which test estimates the volume of fetal blood in her circulation so that the right dose of anti-D immunoglobulin can be given?","options":["Indirect antiglobulin test on cord blood","Kleihauer–Betke (acid elution) test","Haemoglobin electrophoresis on maternal blood","Direct antiglobulin test on the mother"],"correct":1,"explanation":"Fetal red cells contain HbF, which resists acid elution, so they stain dark among pale maternal 'ghost' cells and can be counted to estimate the bleed (flow cytometry is an alternative). A DAT on the mother only shows antibody on her own red cells, not the size of the fetal bleed."},
      {"section":"Haematology and Immunohaematology","topic":"Major Crossmatch","stem":"In a major crossmatch, what is tested?","options":["Patient's plasma against the donor's red cells","Patient's red cells against anti-A and anti-B reagents","Donor plasma against the patient's red cells","Donor red cells against the donor's own plasma"],"correct":0,"explanation":"The major crossmatch tests the recipient's plasma or serum against the donor's red cells, because antibodies in the patient can destroy transfused cells. Donor plasma against patient cells is the minor crossmatch, which is rarely needed with modern red cell concentrates."},
      {"section":"Haematology and Immunohaematology","topic":"Immediate-Spin Crossmatch","stem":"A surgical patient has a negative antibody screen and no history of red cell antibodies. The laboratory performs an immediate-spin crossmatch. What is this crossmatch mainly able to detect?","options":["Weak D antigen on the donor cells","Anti-Jka antibodies in the patient","ABO incompatibility between patient and donor","IgG antibodies to Rh antigens"],"correct":2,"explanation":"An immediate-spin crossmatch at room temperature detects IgM anti-A and anti-B, so it is a check for ABO incompatibility. IgG antibodies such as Rh and Kidd antibodies need an indirect antiglobulin test at 37 °C, which is why immediate spin is used only when the antibody screen is negative."},
      {"section":"Haematology and Immunohaematology","topic":"AHG Check Cells","stem":"An IAT crossmatch tube is negative after adding anti-human globulin (AHG). IgG-coated check cells are then added, but no agglutination is seen. What does this mean?","options":["The donor unit is compatible and can be issued","The patient has no clinically significant antibodies","The donor cells have a negative DAT","The test is invalid (for example, poor washing); repeat it"],"correct":3,"explanation":"Check cells should agglutinate if active AHG is still in the tube; no reaction means the AHG was neutralised by unbound globulin (poor washing) or was left out or inactive. A negative result from an invalid test cannot be trusted, so the unit must not be issued until the test is repeated."},
      {"section":"Haematology and Immunohaematology","topic":"Sample Timing for Crossmatch","stem":"A patient was transfused 3 weeks ago and now needs more blood. How recently must the sample for antibody screening and crossmatch have been taken?","options":["Within 3 days (72 hours) before the transfusion","Within 14 days before the planned transfusion","Within 7 days before the planned transfusion","Any sample from the last 28 days"],"correct":0,"explanation":"A transfusion or pregnancy in the past 3 months can stimulate new red cell antibodies within days, so the sample must be taken no more than 3 days before the transfusion. A 7-day-old sample is acceptable only in patients not transfused or pregnant in the past 3 months."},
      {"section":"Haematology and Immunohaematology","topic":"Incompatible Crossmatch","stem":"A patient's antibody screen and autocontrol are negative. One donor unit is compatible at immediate spin but incompatible at the AHG phase; other units are compatible. What is the most likely explanation?","options":["A warm autoantibody coating the patient's own cells","Antibody to a low-frequency antigen on that donor's cells","Anti-A1 in the plasma of an A2 patient","ABO incompatibility between patient and this donor"],"correct":1,"explanation":"Screening cells do not carry rare (low-frequency) antigens, so such an antibody gives a negative screen but reacts with the one donor who has the antigen; a positive DAT on the donor cells is the other possible cause. A warm autoantibody would make the autocontrol and screen positive, and ABO incompatibility would show at immediate spin."},
      {"section":"Haematology and Immunohaematology","topic":"Sample Labelling","stem":"A crossmatch request arrives with a tube labelled only with the patient's name. The hospital number and date of birth are missing, but the request form is complete. What should the laboratory do?","options":["Reject the sample and ask for a new, correctly labelled sample","Test it but issue only group O RhD negative units","Phone the ward and write the missing details on the tube","Group the sample and copy the missing details from the form"],"correct":0,"explanation":"Transfusion samples need full patient identifiers on the tube; incomplete labels risk 'wrong blood in tube', the main cause of ABO-incompatible transfusion. The laboratory must not add or copy details onto a tube, so the sample is rejected and repeated."},
      {"section":"Haematology and Immunohaematology","topic":"Antibody Screening Cells","stem":"Why are the red cells used for antibody screening always group O?","options":["So that the patient's anti-A or anti-B does not react with them","Group O cells are the only cells that react with AHG","Group O cells are least likely to haemolyse in storage","Group O cells carry more Rh antigens than other groups"],"correct":0,"explanation":"Group O cells have no A or B antigen, so the patient's naturally occurring anti-A and anti-B cannot react, and any reaction shows an unexpected antibody. Rh antigen content has nothing to do with the ABO group of the cells."},
      {"section":"Haematology and Immunohaematology","topic":"Kidd Antibodies","stem":"Eight days after a transfusion, a patient becomes jaundiced and her Hb falls. Her antibody screen before the transfusion was negative. Which new antibody is most often responsible for this kind of reaction?","options":["Anti-M","Anti-Jka","Anti-Lea","Anti-P1"],"correct":1,"explanation":"Kidd antibodies often fall to undetectable levels, then rise quickly after re-exposure, making them a classic cause of delayed haemolytic transfusion reactions. Anti-Lea, anti-M and anti-P1 are usually IgM cold antibodies that are rarely clinically significant."},
      {"section":"Haematology and Immunohaematology","topic":"Enzyme-Treated Panels","stem":"An antibody reacts by IAT with some panel cells but does not react with the same cells after they are treated with papain. Which specificity is most likely?","options":["Anti-Fya","Anti-c","Anti-D","Anti-Jka"],"correct":0,"explanation":"Papain and ficin destroy Duffy (Fya, Fyb), M and N antigens, so these antibodies stop reacting with enzyme-treated cells. Rh antibodies (anti-D, anti-c) and Kidd antibodies (anti-Jka) react more strongly with enzyme-treated cells."},
      {"section":"Haematology and Immunohaematology","topic":"Antibodies and HDFN","stem":"Antenatal antibody screening finds an antibody in each of four pregnant women. Which antibody is LEAST likely to cause haemolytic disease of the fetus and newborn?","options":["Anti-K","Anti-D","Anti-Lea","Anti-c"],"correct":2,"explanation":"Lewis antibodies are mostly IgM, which does not cross the placenta, and Lewis antigens are poorly developed on fetal red cells. Anti-K can cause severe HDFN by suppressing fetal red cell production, and anti-D and anti-c are well-known causes."},
      {"section":"Haematology and Immunohaematology","topic":"Antibody Identification Panel","stem":"An 11-cell panel is tested by IAT. Cells 2, 5 and 7 react 2+; all other cells are negative and the autocontrol is negative. K antigen is present on cells 2, 5 and 7 only. Cells 2, 5, 7 and 9 are E+e− (homozygous). Cells 2, 3, 5, 7 and 8 are Jk(a+b−) (homozygous). Which antibody is most likely present?","options":["A warm autoantibody","Anti-K","Anti-E","Anti-Jka"],"correct":1,"explanation":"Anti-E is ruled out because homozygous E+ cell 9 is negative, and anti-Jka is ruled out because homozygous Jk(a+) cells 3 and 8 are negative; only K matches the reaction pattern exactly. A negative autocontrol and reactions with only some cells argue against an autoantibody; the patient's cells should then be shown to be K negative."},
      {"section":"Haematology and Immunohaematology","topic":"Direct Antiglobulin Test","stem":"A baby born to a group O mother becomes jaundiced on day 1. Which test shows whether maternal IgG antibody is coating the baby's red cells?","options":["Kleihauer test on the baby's blood","Direct antiglobulin test on the baby's red cells","Indirect antiglobulin test on the baby's plasma","Antibody titre on the baby's plasma"],"correct":1,"explanation":"The DAT detects antibody that has already coated red cells in the body, such as maternal IgG on the baby's cells in HDFN. The indirect antiglobulin test detects free antibody in plasma after an in-vitro incubation step, not antibody already bound to the baby's cells."},
      {"section":"Microbiology","topic":"RPR Prozone","stem":"Serum from a woman with a widespread rash and suspected secondary syphilis gives a non-reactive RPR when tested undiluted, but the TPHA is strongly positive. What should be done?","options":["Repeat the RPR on diluted serum to rule out a prozone reaction","Repeat the TPHA after heating the serum to 100 °C","Report the TPHA as a false positive","Report the patient as syphilis negative"],"correct":0,"explanation":"Very high antibody levels in secondary syphilis can block flocculation (prozone), so diluting the serum gives a reactive RPR. Reporting negative would miss an infectious case."},
      {"section":"Microbiology","topic":"Syphilis Treatment Monitoring","stem":"Which test is used to monitor the response to syphilis treatment?","options":["TPHA titre","Treponemal rapid test","Dark-field microscopy","Quantitative RPR titre"],"correct":3,"explanation":"Non-treponemal titres (RPR) fall after successful treatment, so a fourfold fall shows response. Treponemal tests such as TPHA usually stay positive for life."},
      {"section":"Microbiology","topic":"Rapid Test Validity","stem":"An HIV rapid test shows a line in the test area but no line in the control area. How should it be interpreted?","options":["Non-reactive","Reactive","Invalid; repeat with a new test device","Weakly reactive; retest after 14 days"],"correct":2,"explanation":"Without a control line the test did not run properly, so the test line cannot be trusted. Reporting it as reactive is the common mistake."},
      {"section":"Microbiology","topic":"Cryptococcus India Ink","stem":"An India ink preparation of CSF from a man with advanced HIV shows round budding yeasts surrounded by a wide clear halo. Which organism is this?","options":["Histoplasma capsulatum","Candida albicans","Cryptococcus neoformans","Pneumocystis jirovecii"],"correct":2,"explanation":"The clear halo is the polysaccharide capsule of Cryptococcus, outlined by the ink. Candida also forms budding yeasts but has no capsule."},
      {"section":"Microbiology","topic":"Cryptococcal Antigen","stem":"A man with advanced HIV has headache and neck stiffness. CSF India ink is negative. Which test should be done next on the CSF to best detect cryptococcal meningitis?","options":["Repeat India ink after one week","Gram stain","Ziehl–Neelsen stain","Cryptococcal antigen (CrAg) lateral flow assay"],"correct":3,"explanation":"CrAg detection is much more sensitive than India ink, especially when there are few yeasts. Repeating India ink a week later delays diagnosis and is still less sensitive."},
      {"section":"Microbiology","topic":"Germ Tube Test","stem":"A yeast from a vaginal swab is placed in serum at 37 °C. After 2–3 hours, short tube-like outgrowths without a narrowing at the base are seen. Which organism is this?","options":["Candida tropicalis","Candida albicans","Candida glabrata","Cryptococcus neoformans"],"correct":1,"explanation":"True germ tubes within 2–3 hours identify C. albicans. C. tropicalis may form pseudohyphae, but these have a constriction where they join the cell."},
      {"section":"Microbiology","topic":"KOH Preparation","stem":"Why is 10–20% potassium hydroxide (KOH) added to skin scrapings for fungal microscopy?","options":["It fixes the fungi to the slide","It kills bacteria so only fungi remain","It stains fungal walls blue","It digests keratin and clears cells so fungal hyphae can be seen"],"correct":3,"explanation":"KOH breaks down keratin and host cells while fungal walls resist it. Staining fungi blue is the role of lactophenol cotton blue, not KOH."},
      {"section":"Microbiology","topic":"Pityriasis Versicolor","stem":"Scrapings from pale scaly patches on a young man's back show short curved hyphae and clusters of round yeast cells (\"spaghetti and meatballs\"). What is the cause?","options":["Microsporum canis","Candida albicans","Malassezia furfur","Trichophyton rubrum"],"correct":2,"explanation":"Short hyphae with grape-like yeast clusters are typical of Malassezia, the cause of pityriasis versicolor. Dermatophytes such as Trichophyton show long branching septate hyphae without yeast clusters."},
      {"section":"Microbiology","topic":"Sabouraud Additives","stem":"Why should Sabouraud agar containing cycloheximide not be the only medium used to culture CSF for suspected cryptococcal meningitis?","options":["Cycloheximide encourages overgrowth by moulds","Cycloheximide inhibits Cryptococcus neoformans","Cycloheximide makes the medium too acidic for yeasts","Cycloheximide destroys the capsule, making India ink negative"],"correct":1,"explanation":"Cycloheximide suppresses saprophytic moulds but also inhibits C. neoformans, so CSF should go on a medium without it. It does not encourage moulds; it suppresses them."},
      {"section":"Microbiology","topic":"Lactophenol Cotton Blue","stem":"Which reagent is used to mount and stain material from a fungal colony to study its hyphae and spores under the microscope?","options":["Giemsa stain","Lactophenol cotton blue","India ink","10% potassium hydroxide"],"correct":1,"explanation":"Lactophenol kills and preserves the fungus and cotton blue stains its walls, showing spores and hyphae. KOH clears clinical specimens such as skin but does not stain culture material."},
      {"section":"Microbiology","topic":"Aspergillus","stem":"A lung tissue section from a neutropenic patient shows narrow septate hyphae branching regularly at acute angles (about 45°). Which fungus is most likely?","options":["Candida albicans","Cryptococcus neoformans","Mucor or Rhizopus species","Aspergillus species"],"correct":3,"explanation":"Narrow septate hyphae with acute-angle branching suggest Aspergillus. Mucorales have broad, ribbon-like, mostly aseptate hyphae branching at right angles."},
      {"section":"Microbiology","topic":"Pneumocystis","stem":"Why is Pneumocystis jirovecii pneumonia diagnosed by microscopy or PCR of induced sputum or bronchoalveolar lavage, rather than by culture?","options":["The organism is killed by sputum transport media","Culture takes 6–8 weeks, like M. tuberculosis","The organism cannot be grown on routine culture media","Culture grows only the cyst form"],"correct":2,"explanation":"P. jirovecii cannot be cultured in the routine laboratory, so stains (Giemsa, silver, immunofluorescence) or PCR are used. Slow growth over weeks is a feature of M. tuberculosis, not Pneumocystis."},
      {"section":"Microbiology","topic":"Histoplasma","stem":"A bone marrow smear from a man with advanced HIV shows many small oval yeasts (2–4 µm) inside macrophages, each with a clear halo and no kinetoplast. Which organism is most likely?","options":["Cryptococcus neoformans","Histoplasma capsulatum","Toxoplasma gondii","Leishmania donovani"],"correct":1,"explanation":"Small intracellular yeasts with a halo and no kinetoplast suggest Histoplasma. Leishmania amastigotes look similar but have both a nucleus and a rod-shaped kinetoplast."},
      {"section":"Clinical Chemistry","topic":"Light Chains and Dipstick","stem":"A 65-year-old man with bone pain is suspected of having multiple myeloma. His urine dipstick protein is negative, but a sulfosalicylic acid test shows heavy protein. Why do the tests differ?","options":["The urine was too acidic for any protein test","The dipstick reacts mainly with albumin and misses light chains","Light chains are not filtered by the glomerulus","Sulfosalicylic acid detects only albumin"],"correct":1,"explanation":"The dipstick protein pad works by the \"protein error of indicators\" and is much more sensitive to albumin than to free light chains (Bence Jones protein). Acid precipitation tests detect all proteins; urine protein electrophoresis/immunofixation confirms light chains."},
      {"section":"Clinical Chemistry","topic":"Blood Pad Without Red Cells","stem":"A man rescued from a collapsed building has dark urine. The dipstick shows blood 3+, but microscopy of the fresh urine shows no red cells. What is the most likely cause?","options":["Nitrite made by urinary bacteria","Ascorbic acid in the urine","Myoglobin released from injured muscle","Bilirubin reacting with the blood pad"],"correct":2,"explanation":"The blood pad detects the peroxidase-like activity of haem, so it is positive with free haemoglobin or myoglobin even without intact red cells; crush injury points to myoglobin from rhabdomyolysis. Ascorbic acid causes false-negative, not false-positive, blood results."},
      {"section":"Clinical Chemistry","topic":"Delayed Urine Testing","stem":"A urine sample is left at room temperature for 8 hours before dipstick testing. Which change is expected?","options":["Nitrite falls as bacteria use it up","Glucose rises as bacteria produce sugar","pH rises as bacteria convert urea to ammonia","Urobilinogen rises from exposure to light"],"correct":2,"explanation":"Bacteria multiply in unpreserved urine and break urea down to ammonia, making the urine more alkaline; they also consume glucose and can raise nitrite. Urobilinogen is unstable and falls with time and light, so urine should be tested within 2 hours or refrigerated."},
      {"section":"Clinical Chemistry","topic":"Vitamin C Interference","stem":"A patient is taking high-dose vitamin C tablets. Which urine dipstick results may be falsely negative?","options":["Glucose and blood","Ketones and pH","Protein and pH","Specific gravity and protein"],"correct":0,"explanation":"Ascorbic acid is a strong reducing agent that removes the hydrogen peroxide or oxidised dye in the glucose oxidase and blood (peroxidase) reactions, giving false-negative results. Protein and pH pads use indicator dyes and are not affected in this way."},
      {"section":"Clinical Chemistry","topic":"Transmittance to Absorbance","stem":"A coloured solution transmits 10% of the incident light in a spectrophotometer. What is its absorbance?","options":["1.0","0.1","0.9","2.0"],"correct":0,"explanation":"Absorbance A = -log T = 2 - log(%T) = 2 - log 10 = 2 - 1 = 1.0. A common error is to take 0.1 (the fraction transmitted) as the absorbance."},
      {"section":"Clinical Chemistry","topic":"Concentration From Standard","stem":"In a colorimetric test, a 10 mmol/L standard gives an absorbance of 0.40 and the patient sample gives 0.30, both read against the same reagent blank. Assuming Beer's law holds, what is the sample concentration?","options":["3.0 mmol/L","7.5 mmol/L","13.3 mmol/L","12.0 mmol/L"],"correct":1,"explanation":"Concentration of test = (A test / A standard) x concentration of standard = (0.30 / 0.40) x 10 = 7.5 mmol/L. Inverting the ratio (0.40/0.30 x 10) gives the wrong answer of 13.3 mmol/L."},
      {"section":"Clinical Chemistry","topic":"Reagent Blank Purpose","stem":"Why is a reagent blank read before the standards and patient samples in an end-point colorimetric method?","options":["To calculate the molar absorptivity of the product","To correct for haemolysis in each patient sample","To remove absorbance due to the reagent and cuvette","To check that the wavelength setting is accurate"],"correct":2,"explanation":"Setting zero absorbance with a reagent blank removes the colour of the reagent itself and the cuvette, so the reading reflects only the product from the analyte. Correcting for a patient's own sample colour (such as haemolysis) needs a separate sample blank."},
      {"section":"Clinical Chemistry","topic":"Result Above Linear Range","stem":"A sample gives an absorbance of 2.4 in a method whose stated linear limit is 1.5 absorbance units. What should the technologist do?","options":["Increase the sample volume and repeat the test","Dilute the sample, repeat, and multiply by the dilution factor","Read at another wavelength and report that result","Report the result calculated from the standard as usual"],"correct":1,"explanation":"Above the linear range the absorbance no longer rises in proportion to concentration (deviation from Beer's law), so the result would be wrong; diluting brings it back into range. Increasing the sample volume would raise the absorbance further."},
      {"section":"Clinical Chemistry","topic":"Enzyme Activity Calculation","stem":"In a kinetic ALT assay, NADH absorbance at 340 nm falls by 0.050 per minute. Total reaction volume is 1.0 mL, sample volume 0.1 mL, light path 1 cm, and NADH molar absorptivity 6,220 L/mol/cm. What is the ALT activity?","options":["About 0.8 U/L","About 80 U/L","About 804 U/L","About 8 U/L"],"correct":1,"explanation":"U/L = (ΔA/min x total volume x 10⁶) / (ε x light path x sample volume) = (0.050 x 1.0 x 10⁶) / (6,220 x 1 x 0.1) = 50,000 / 622 = 80.4 U/L. Leaving out the sample volume term (dividing by 6,220 instead of 622) gives about 8 U/L."},
      {"section":"Clinical Chemistry","topic":"Dilution Factor Correction","stem":"A glucose result is above the linear range, so 100 µL of serum is mixed with 400 µL of saline and re-tested. The diluted sample reads 9.2 mmol/L. What result should be reported?","options":["92.0 mmol/L","36.8 mmol/L","46.0 mmol/L","11.5 mmol/L"],"correct":2,"explanation":"100 µL serum in a total of 500 µL is a 1 in 5 dilution, so the result is 9.2 x 5 = 46.0 mmol/L. Multiplying by 4 (the volume of diluent only) gives the wrong answer of 36.8 mmol/L."},
      {"section":"Clinical Chemistry","topic":"Serial Dilution","stem":"Serum is diluted 1 in 2 with saline. That diluted serum is then diluted 1 in 10. What is the final dilution of the original serum?","options":["1 in 200","1 in 20","1 in 12","1 in 5"],"correct":1,"explanation":"In serial dilutions the dilution factors are multiplied: 2 x 10 = 20, so the final dilution is 1 in 20. Adding the factors (2 + 10 = 12) is a common error."},
      {"section":"Clinical Chemistry","topic":"Preparing a Molar Solution","stem":"How much sodium hydroxide (NaOH, molar mass 40 g/mol) is needed to make 250 mL of a 0.5 mol/L solution?","options":["20.0 g","2.0 g","5.0 g","50.0 g"],"correct":2,"explanation":"Moles needed = 0.5 mol/L x 0.25 L = 0.125 mol; mass = 0.125 x 40 = 5.0 g. Using 1 L instead of 0.25 L gives 20.0 g."},
      {"section":"Histopathology and Laboratory Management","topic":"Calcified Tissue and Cryostat","stem":"A surgeon sends a piece of hard, calcified bone and asks for an urgent frozen section. What is the best response?","options":["Freeze it more slowly so the calcium softens","Explain that calcified bone cannot be cut on the cryostat; it needs fixation and decalcification","Cut it on the cryostat at a warmer setting","Put it in formalin for 10 minutes and then cut frozen sections"],"correct":1,"explanation":"Calcified bone is too hard for the cryostat blade and will damage it and give no useful sections; it must be fixed and decalcified for paraffin sections. A short formalin bath does nothing to remove calcium."},
      {"section":"Histopathology and Laboratory Management","topic":"Westgard 1-3s Rule","stem":"A glucose control has a mean of 5.0 mmol/L and SD of 0.1 mmol/L. Today it reads 5.35 mmol/L. What should the technician do?","options":["Accept the run: 1-2s warning only","Reject the run: 10x violation","Accept the run because only one control is out","Reject the run: 1-3s violation"],"correct":3,"explanation":"(5.35 - 5.0) / 0.1 = 3.5 SD above the mean, which breaks the 1-3s rule, so the run is rejected and patient results are held while the cause (usually random error) is found. It is more than a 1-2s warning because the value is beyond 3 SD."},
      {"section":"Histopathology and Laboratory Management","topic":"Westgard 1-2s Warning","stem":"Two control levels are run. Level 1 is +2.4 SD and level 2 is +0.5 SD. All previous runs were within 1 SD, scattered on both sides of the mean. What is the correct action?","options":["Treat it as a 1-2s warning; check the other rules and accept the run","Reject the run and recalibrate the analyser at once","Reject the run: R-4s violation","Reject the run: 2-2s violation"],"correct":0,"explanation":"One control between 2 and 3 SD is a 1-2s warning that triggers checking of the other rules; here 2-2s (needs both beyond +2 SD), R-4s (range is only 2.4 - 0.5 = 1.9 SD), 4-1s and 10x are not broken, so the run is accepted. Rejecting on 1-2s alone causes many false rejections."},
      {"section":"Histopathology and Laboratory Management","topic":"Westgard 2-2s Rule","stem":"In one run, both the normal and high control for creatinine are between +2 SD and +3 SD. What does this show?","options":["An R-4s violation, suggesting random error","A 2-2s violation, suggesting systematic error","Normal variation; the run can be accepted","A 1-3s violation, suggesting random error"],"correct":1,"explanation":"Two controls beyond 2 SD on the same side (here both above +2 SD) break the 2-2s rule, which points to systematic error such as a calibration or reagent problem; the run is rejected. It is not 1-3s because neither control is beyond 3 SD."},
      {"section":"Histopathology and Laboratory Management","topic":"Westgard R-4s Rule","stem":"In one run, the low control is +2.3 SD and the high control is -2.1 SD. Which Westgard rule is broken?","options":["R-4s, showing random error","4-1s, showing systematic error","2-2s, showing systematic error","10x, showing systematic error"],"correct":0,"explanation":"The range between the two controls is 2.3 + 2.1 = 4.4 SD, with one above +2 SD and one below -2 SD, which breaks R-4s and indicates random error (e.g. a bubble or pipetting fault). It is not 2-2s, because the controls are on opposite sides of the mean."},
      {"section":"Histopathology and Laboratory Management","topic":"Westgard 10x Rule","stem":"On a Levey-Jennings chart, the last 10 consecutive values of one control are all above the mean, but all within +2 SD. What does this show?","options":["Acceptable results, since none is beyond 2 SD","An R-4s violation, showing random error","A 10x violation, showing systematic error","A 1-3s violation, showing random error"],"correct":2,"explanation":"Ten consecutive results on the same side of the mean break the 10x rule and show a systematic shift (for example, a new reagent lot or calibration change), even when each value is within 2 SD. Accepting them because each one is \"within limits\" misses this bias."},
      {"section":"Histopathology and Laboratory Management","topic":"Coefficient of Variation","stem":"Twenty days of data for a glucose control give a mean of 6.0 mmol/L and an SD of 0.3 mmol/L. What is the coefficient of variation (CV)?","options":["20%","0.05%","5%","1.8%"],"correct":2,"explanation":"CV = (SD / mean) x 100 = (0.3 / 6.0) x 100 = 5%. 20% comes from dividing the mean by the SD (6.0 / 0.3) instead of the SD by the mean."},
      {"section":"Histopathology and Laboratory Management","topic":"Trend on Levey-Jennings Chart","stem":"Over 8 days, a control value rises a little each day on the Levey-Jennings chart, moving steadily away from the mean. What is the most likely explanation?","options":["Normal variation that needs no action","Random error, from a single pipetting mistake","A shift, from a sudden change such as a new reagent lot","A trend, from gradual deterioration such as an ageing lamp or reagent"],"correct":3,"explanation":"A gradual, steady movement in one direction is a trend and suggests slow deterioration of a reagent, lamp or other component. A shift is a sudden jump to a new level, typically after a new lot or recalibration."},
      {"section":"Histopathology and Laboratory Management","topic":"Handling EQA Samples","stem":"A hospital lab receives a proficiency testing (EQA) panel from an external provider. How should the samples be tested?","options":["Only after a special recalibration of the analyser","Like routine patient samples, by the usual staff and methods","Sent to another lab to confirm before reporting","By the most senior technician, repeated several times, reporting the best result"],"correct":1,"explanation":"EQA checks how the lab performs in daily work, so samples must be handled exactly like patient samples. Repeating tests, using only senior staff or getting help from another lab hides real problems and defeats the purpose."},
      {"section":"Histopathology and Laboratory Management","topic":"Biological Safety Cabinet Classes","stem":"A lab needs a cabinet that protects the worker, the specimen and the environment while handling infectious material. Which should it use?","options":["Horizontal laminar flow clean bench","Chemical fume hood","Class I biological safety cabinet","Class II biological safety cabinet"],"correct":3,"explanation":"A Class II cabinet combines inward airflow (protecting the worker) with HEPA-filtered downflow (protecting the specimen) and HEPA-filtered exhaust (protecting the environment). A Class I cabinet protects the worker and environment but not the specimen, because unfiltered room air passes over the work."},
      {"section":"Histopathology and Laboratory Management","topic":"Risk Group Definitions","stem":"Mycobacterium tuberculosis is classed as a Risk Group 3 organism. What does Risk Group 3 mean?","options":["Moderate individual risk, low community risk","High individual risk, low community risk","High individual risk and high community risk","No or low individual and community risk"],"correct":1,"explanation":"Risk Group 3 agents usually cause serious human disease but do not ordinarily spread easily between people, and effective treatment and prevention exist. High individual and high community risk describes Risk Group 4 (for example, Ebola virus)."},
      {"section":"Histopathology and Laboratory Management","topic":"TB Laboratory Biosafety","stem":"A district hospital lab does only direct sputum smear microscopy and Xpert MTB/RIF testing. What does WHO guidance say about where these can be done?","options":["Only inside a Class III cabinet","Only inside a TB containment (BSL-3) laboratory","On an open bench in a well-ventilated area, using good technique","Only in a Class II cabinet in a negative-pressure room"],"correct":2,"explanation":"WHO classes direct smear microscopy and Xpert sample preparation as low-risk procedures, because viscous sputum makes few aerosols; they can be done on an open bench with good ventilation. Containment-level facilities are needed for manipulating TB cultures, not these tests."},
    ],
  },
  {
    country: 'RW', category: 'licensing-exams',
    profession: {"slug":"rahpc-biomedical-laboratory-sciences-licensing-exam","name":"Biomedical Laboratory Sciences Licensing Exam (RAHPC)"},
    slug: "rahpc-biomedical-laboratory-sciences-mock-exam-5",
    title: "Biomedical Laboratory Sciences Licensing Exam (RAHPC) — Mock Exam 5",
    summary: "Haematology and Immunohaematology; Microbiology; Clinical Chemistry; Histopathology and Laboratory Management.",
    free: false, difficulty: 'STANDARD', minutes: 60,
    instructions: ["50 multiple-choice questions, one best answer each, 60 minutes.","RAHPC does not publish the number of questions or the time of its registry exam; these mocks cover its published thematic areas."],
    sections: [{"name":"Haematology and Immunohaematology"},{"name":"Microbiology"},{"name":"Clinical Chemistry"},{"name":"Histopathology and Laboratory Management"}],
    questions: [
      {"section":"Haematology and Immunohaematology","topic":"Acute Haemolytic Reaction","stem":"Fifteen minutes into a red cell transfusion, a patient develops fever, back pain, low blood pressure and red urine. The transfusion is stopped, and the bag and a new blood sample are sent to the laboratory. What should the laboratory do first?","options":["Send the bag for bacterial culture and take no other action","Measure serum IgA and test for anti-IgA antibodies","Check labels and records for an ID error; repeat ABO group and DAT","Crossmatch and issue another unit of the same group at once"],"correct":2,"explanation":"These signs suggest an acute haemolytic reaction, most often ABO incompatibility caused by an identification error, so the first step is a clerical check plus a repeat ABO group and DAT on the post-transfusion sample. Issuing more blood before the cause is known could repeat the same error."},
      {"section":"Haematology and Immunohaematology","topic":"Febrile Non-Haemolytic Reaction","stem":"A man with sickle cell disease who has had many transfusions develops chills and a temperature rise from 37.0 °C to 38.3 °C one hour into a red cell transfusion. His blood pressure is normal, there is no rash or breathlessness, and haemolysis tests are negative. Which change to future components is most likely to prevent this reaction?","options":["Gamma irradiation","Leucocyte reduction","Washing with saline","Using group O units only"],"correct":1,"explanation":"This is a febrile non-haemolytic reaction caused by cytokines and antibodies against donor white cells, which leucocyte reduction lowers. Irradiation prevents transfusion-associated graft-versus-host disease, not fever."},
      {"section":"Haematology and Immunohaematology","topic":"Anaphylactic Reaction","stem":"Within minutes of starting a plasma transfusion, a patient develops wheeze, low blood pressure and swollen lips. Tests later show she has IgA deficiency with anti-IgA antibodies. Which components should she receive in future?","options":["Gamma-irradiated cellular components only","Leucocyte-reduced components from any donor","Fresh red cells, less than 5 days old","Washed red cells or IgA-deficient donor components"],"correct":3,"explanation":"Her anti-IgA reacts with IgA in donor plasma, so she needs components with the plasma removed (washed red cells) or plasma from IgA-deficient donors. Leucocyte reduction removes white cells, not plasma proteins, so it does not prevent this reaction."},
      {"section":"Haematology and Immunohaematology","topic":"TRALI","stem":"Two hours after receiving fresh frozen plasma, a patient becomes very short of breath with low oxygen saturation, fever and low blood pressure. The chest X-ray shows new infiltrates in both lungs. The JVP is not raised and furosemide does not help. What is the most likely diagnosis?","options":["Transfusion-associated circulatory overload","Transfusion-related acute lung injury","Acute haemolytic reaction","Anaphylactic reaction"],"correct":1,"explanation":"Acute non-cardiogenic lung oedema within 6 hours of transfusion, with low blood pressure and no response to diuretics, is TRALI, often due to donor anti-HLA or anti-neutrophil antibodies. TACO usually causes raised blood pressure and JVP and improves with diuretics."},
      {"section":"Haematology and Immunohaematology","topic":"Bacterial Contamination","stem":"Which blood component has the highest risk of bacterial contamination causing a septic transfusion reaction?","options":["Cryoprecipitate","Fresh frozen plasma","Platelet concentrate","Red cells in SAGM"],"correct":2,"explanation":"Platelets are stored at 20–24 °C, which allows bacteria to grow, so they carry the highest risk of septic reactions. Red cells are kept at 2–6 °C and plasma components are frozen, which limits bacterial growth."},
      {"section":"Haematology and Immunohaematology","topic":"Transfusion-Associated GvHD","stem":"A mother is going to donate blood directly for her 30-year-old son, who needs a transfusion. Which processing step prevents transfusion-associated graft-versus-host disease?","options":["Leucocyte reduction by filtration","Storing the unit for 7 days before use","Gamma or X-ray irradiation","Washing the red cells"],"correct":2,"explanation":"A first-degree relative shares HLA with the recipient, so the donor's lymphocytes may not be rejected and can attack the patient; irradiation stops these lymphocytes from dividing. Leucocyte reduction lowers lymphocyte numbers but does not reliably prevent TA-GvHD."},
      {"section":"Haematology and Immunohaematology","topic":"Red Cell Storage","stem":"At what temperature should red cell units be kept in a hospital blood bank refrigerator?","options":["2 °C to 6 °C","8 °C to 12 °C","20 °C to 24 °C with agitation","−18 °C or colder"],"correct":0,"explanation":"Red cells are stored at 2–6 °C in a monitored blood bank refrigerator to slow metabolism and bacterial growth. 20–24 °C with agitation is the storage condition for platelets, and freezing is used for plasma."},
      {"section":"Haematology and Immunohaematology","topic":"Platelet Storage","stem":"How should platelet concentrates be stored in the hospital blood bank before transfusion?","options":["At −25 °C or colder in the plasma freezer","At 20 °C to 24 °C with continuous gentle agitation","At 2 °C to 6 °C in the red cell refrigerator","At room temperature on the bench, without movement"],"correct":1,"explanation":"Standard platelet concentrates are stored at 20–24 °C on an agitator, which keeps them viable and allows gas exchange through the bag. Refrigerating standard platelets shortens their survival after transfusion, and leaving them still on a bench harms their function."},
      {"section":"Haematology and Immunohaematology","topic":"Blood Shelf Life","stem":"Whole blood is collected into CPDA-1 anticoagulant-preservative, with no additive solution. What is its maximum shelf life at 2–6 °C?","options":["35 days","7 days","42 days","21 days"],"correct":0,"explanation":"The adenine in CPDA-1 helps red cells keep making ATP, giving a shelf life of 35 days. Blood in CPD without adenine lasts 21 days, and red cells resuspended in an additive solution such as SAGM can last up to 42 days."},
      {"section":"Haematology and Immunohaematology","topic":"Cryoprecipitate","stem":"A woman with major bleeding after childbirth has a fibrinogen of 0.8 g/L. Which component gives the most fibrinogen in the smallest volume?","options":["Fresh frozen plasma","Red cells in SAGM","Platelet concentrate","Cryoprecipitate"],"correct":3,"explanation":"Cryoprecipitate is prepared by thawing FFP in the cold and is rich in fibrinogen, factor VIII, von Willebrand factor and factor XIII in a small volume. FFP contains fibrinogen too, but at a much lower concentration, so large volumes are needed."},
      {"section":"Haematology and Immunohaematology","topic":"Donor Infection Screening","stem":"WHO recommends that every donated blood unit is screened, as a minimum, for which infections?","options":["HIV, hepatitis B, hepatitis C and malaria","HIV, hepatitis B, hepatitis C and syphilis","Hepatitis B, hepatitis C, malaria and toxoplasmosis","HIV, HTLV, cytomegalovirus and syphilis"],"correct":1,"explanation":"WHO's minimum mandatory screening for all donations is HIV, hepatitis B, hepatitis C and syphilis. Screening for other infections such as malaria, HTLV or CMV depends on local epidemiology and on the patients being transfused."},
      {"section":"Haematology and Immunohaematology","topic":"Donor Deferral","stem":"Four people come to donate blood at a mobile session. Which one should be deferred?","options":["A 30-year-old man who last gave whole blood 5 months ago","A 45-year-old woman weighing 58 kg with Hb 13.2 g/dL today","A 22-year-old woman who took paracetamol for a headache yesterday","A 27-year-old woman who is 20 weeks pregnant"],"correct":3,"explanation":"Pregnancy is a reason for deferral, to protect the mother's iron stores and the fetus, and deferral continues for a period after delivery. The 58 kg woman with Hb 13.2 g/dL meets the usual weight (at least 50 kg) and haemoglobin (at least 12.5 g/dL) criteria, 5 months is longer than the usual minimum interval between whole blood donations, and paracetamol does not defer a donor."},
      {"section":"Haematology and Immunohaematology","topic":"Inspection Before Issue","stem":"Before issuing a red cell unit, a technologist sees that the bag contents are dark purple-black, with visible clots and red-tinged plasma above the cells. What is the correct action?","options":["Quarantine the unit, do not issue it, and report it","Filter it through a new giving set and then issue it","Issue the unit and tell the ward to give it slowly","Mix the bag well and check it again after 30 minutes"],"correct":0,"explanation":"Dark discolouration, clots and haemolysis suggest bacterial contamination or damage, so the unit must be withheld, quarantined and reported for investigation. Mixing or filtering the bag does not remove bacteria or toxins."},
      {"section":"Microbiology","topic":"Dimorphic Fungi","stem":"A farmer has a nodular ulcer on the hand, with new nodules along the lymphatics of the arm. Pus culture grows a mould at 25 °C and a yeast at 37 °C. Which fungus is most likely?","options":["Aspergillus fumigatus","Sporothrix schenckii","Trichophyton rubrum","Candida albicans"],"correct":1,"explanation":"Spread along lymphatics after a skin injury, with mould at 25 °C and yeast at 37 °C (dimorphism), is typical of sporotrichosis. Trichophyton infects skin but is not dimorphic and does not spread along lymphatics."},
      {"section":"Microbiology","topic":"Xpert Sample Reagent","stem":"For Xpert MTB/RIF testing, a patient gives 2 mL of sputum. How much Sample Reagent should be added?","options":["1 mL","4 mL","2 mL","8 mL"],"correct":1,"explanation":"Sample Reagent is added at 2 volumes to 1 volume of sputum: 2 mL × 2 = 4 mL. Adding an equal volume (2 mL) is the common error."},
      {"section":"Microbiology","topic":"Xpert Sample Processing","stem":"After Sample Reagent is added to sputum for Xpert MTB/RIF, what is the correct processing step?","options":["Incubate 30 minutes at 37 °C without shaking","Shake, leave 10 minutes at room temperature, shake again and leave 5 more minutes","Load the cartridge immediately without waiting","Centrifuge and use only the deposit"],"correct":1,"explanation":"The mixture is shaken, left 10 minutes, shaken again and left 5 minutes (15 minutes in total) to liquefy and inactivate the sample. Loading at once gives poorly liquefied sputum and possible errors."},
      {"section":"Microbiology","topic":"Xpert Resistance Target","stem":"Xpert MTB/RIF detects rifampicin resistance by finding mutations in which gene?","options":["inhA","rpoB","katG","gyrA"],"correct":1,"explanation":"The assay targets the rifampicin-resistance-determining region of rpoB. katG and inhA mutations cause isoniazid resistance, and gyrA mutations cause fluoroquinolone resistance."},
      {"section":"Microbiology","topic":"Rifampicin-resistant TB","stem":"An Xpert result reads \"MTB DETECTED; RIF Resistance DETECTED\". What does this mean?","options":["Drug-susceptible TB; start first-line treatment","Isoniazid resistance only; continue first-line drugs","Non-tuberculous mycobacteria; no TB treatment is needed","Rifampicin-resistant TB; refer for DR-TB treatment and further DST"],"correct":3,"explanation":"Detected rpoB mutations mean rifampicin-resistant TB, managed under drug-resistant TB guidelines with further DST for other drugs. Xpert MTB/RIF does not test isoniazid at all."},
      {"section":"Microbiology","topic":"Xpert Ultra Trace","stem":"Xpert MTB/RIF Ultra gives \"MTB Trace DETECTED\". What will the rifampicin result show?","options":["RIF Resistance INDETERMINATE","RIF Resistance DETECTED","INVALID","RIF Resistance NOT DETECTED"],"correct":0,"explanation":"A trace result means very few bacilli, too few to read the rpoB probes, so rifampicin resistance is reported as indeterminate. \"Not detected\" would wrongly suggest the strain is known to be susceptible."},
      {"section":"Microbiology","topic":"Xpert Invalid Result","stem":"An Xpert MTB/RIF run gives the result \"INVALID\". What is the best action?","options":["Report \"MTB not detected\"","Re-run the same used cartridge","Repeat on a new cartridge, using leftover sample or a new specimen","Report \"MTB detected, rifampicin indeterminate\""],"correct":2,"explanation":"INVALID means the sample processing control failed (poor processing or PCR inhibition), so no TB result can be given; the package insert says to retest on a new cartridge using leftover sample (SR-treated within 4 hours, or fresh sputum with new Sample Reagent) or a new specimen. Reporting it as negative could miss TB."},
      {"section":"Microbiology","topic":"Xpert Treatment Monitoring","stem":"Why is Xpert MTB/RIF not used to monitor response during TB treatment?","options":["It detects only rifampicin-resistant strains","It detects DNA from dead as well as live bacilli","It cannot detect bacilli after the intensive phase","It needs at least 10 000 bacilli/mL to be positive"],"correct":1,"explanation":"DNA from dead bacilli can keep Xpert positive in patients who are responding, so smear microscopy (and culture) is used for follow-up. Xpert is very sensitive, so it does not need a high bacillary load."},
      {"section":"Microbiology","topic":"Xpert Extrapulmonary Specimens","stem":"A man with HIV is suspected to have TB meningitis. Which specimen should be sent for Xpert MTB/RIF Ultra?","options":["Serum","Cerebrospinal fluid","EDTA whole blood","Urine"],"correct":1,"explanation":"WHO recommends Xpert Ultra on CSF for TB meningitis. Urine is used for the LF-LAM test, not for Xpert in this case."},
      {"section":"Microbiology","topic":"Xpert Internal Controls","stem":"What does the Sample Processing Control (SPC) in an Xpert MTB/RIF cartridge check?","options":["That the module temperature is calibrated","That the sample was processed properly and no PCR inhibitors are present","That rifampicin resistance was correctly detected","That the probes and reagents are intact before the run"],"correct":1,"explanation":"The SPC confirms adequate processing and no inhibition; if it fails and MTB is not detected, the result is INVALID. Probe and reagent integrity is checked by the separate Probe Check Control."},
      {"section":"Microbiology","topic":"Xpert Biosafety","stem":"Xpert sputum processing can be done with the same biosafety precautions as direct smear microscopy. Why?","options":["The cartridge is sealed before the sputum is added","The test uses only 0.1 mL of sputum","The Sample Reagent kills most TB bacilli before the sample is handled further","TB bacilli cannot form aerosols from liquid sputum"],"correct":2,"explanation":"The Sample Reagent (sodium hydroxide and isopropanol) inactivates the bacilli, so the risk is similar to smear preparation. The cartridge is opened to add the sample, so it is not sealed at that step."},
      {"section":"Microbiology","topic":"Xpert Smear-negative TB","stem":"A 30-year-old man who has never had TB has a sputum smear negative for AFB, but Xpert MTB/RIF shows \"MTB DETECTED; RIF Resistance NOT DETECTED\". What is the correct interpretation?","options":["Clinically diagnosed TB only; wait for culture","Confirmed rifampicin-susceptible TB; start first-line treatment","Latent TB infection; no treatment needed","A false-positive Xpert, because the smear is negative"],"correct":1,"explanation":"Xpert is more sensitive than smear, so a positive Xpert confirms TB even when the smear is negative. In someone never treated for TB, DNA from old dead bacilli is not a concern."},
      {"section":"Microbiology","topic":"Xpert Negative Result","stem":"An adult with advanced HIV has cough and weight loss, but sputum Xpert Ultra shows \"MTB NOT DETECTED\". The clinician still suspects TB. What is the best interpretation?","options":["TB is excluded and no further TB tests are needed","TB is not excluded; further tests such as urine LF-LAM are needed","The result is invalid and must be repeated on the same sample","The patient has rifampicin-resistant TB"],"correct":1,"explanation":"People with advanced HIV often have few bacilli in sputum, so a negative Xpert does not rule out TB; urine LF-LAM, culture and clinical review should follow. NOT DETECTED is a valid result, not an invalid one."},
      {"section":"Clinical Chemistry","topic":"Working Standard Preparation","stem":"A stock standard contains 100 mmol/L of analyte. What volume of stock is needed to make 200 mL of a 5 mmol/L working standard?","options":["10 mL","20 mL","40 mL","2.5 mL"],"correct":0,"explanation":"Using C1V1 = C2V2: 100 x V1 = 5 x 200, so V1 = 1,000 / 100 = 10 mL, made up to 200 mL with diluent. 20 mL would give 10 mmol/L, twice the needed strength."},
      {"section":"Clinical Chemistry","topic":"Glucose Unit Conversion","stem":"A referral letter reports a plasma glucose of 162 mg/dL. Glucose has a molar mass of 180 g/mol. What is this value in mmol/L?","options":["90 mmol/L","2.9 mmol/L","0.9 mmol/L","9.0 mmol/L"],"correct":3,"explanation":"162 mg/dL = 1,620 mg/L; 1,620 mg/L / 180 g/mol = 9.0 mmol/L (the short cut is mg/dL / 18). Forgetting that a decilitre is one tenth of a litre gives 0.9 mmol/L."},
      {"section":"Clinical Chemistry","topic":"Percent to Molar Concentration","stem":"Normal saline is 0.9% w/v sodium chloride. If NaCl has a molar mass of 58.5 g/mol, what is its sodium chloride concentration?","options":["15.4 mmol/L","1,540 mmol/L","90 mmol/L","154 mmol/L"],"correct":3,"explanation":"0.9% w/v = 0.9 g per 100 mL = 9 g/L; 9 / 58.5 = 0.154 mol/L = 154 mmol/L. Using 0.9 g/L instead of 9 g/L gives 15.4 mmol/L."},
      {"section":"Clinical Chemistry","topic":"Meaning of Reference Interval","stem":"Most laboratory reference intervals are set as the central 95% of results from healthy people. What does this mean in practice?","options":["About 1 in 20 healthy people will have a result outside the interval","About 95% of sick patients will have results inside it","Any result outside the interval means the patient has a disease","Every patient with the disease will have a result outside it"],"correct":0,"explanation":"Using the 2.5th to 97.5th percentiles leaves 5% of healthy people (1 in 20) outside the interval by definition, so a slightly abnormal result is not proof of disease. The interval says nothing directly about how many sick patients fall inside or outside it."},
      {"section":"Clinical Chemistry","topic":"Multiple Tests in Healthy People","stem":"A healthy person has a panel of 20 independent tests, each with a 95% reference interval. What is the chance that at least one result falls outside its interval?","options":["Almost 100%","About 64%","About 5%","About 36%"],"correct":1,"explanation":"The chance that all 20 are inside is 0.95²⁰ = 0.36, so the chance that at least one is outside is 1 - 0.36 = 0.64 (about 64%). 36% is the chance that all results are normal, not that one is abnormal."},
      {"section":"Clinical Chemistry","topic":"Verifying a Reference Interval","stem":"A district hospital laboratory installs a new analyser and wants to use the manufacturer's reference interval. It tests 20 samples from healthy local adults, and 1 result falls outside the interval. Following CLSI guidance, what should it do?","options":["Reject the interval and recruit 120 people for a new one","Adopt the interval, as 2 or fewer of 20 outside is acceptable","Widen the interval so that the outlying result fits inside","Test 20 more healthy people before deciding"],"correct":1,"explanation":"CLSI EP28-A3c lets a laboratory verify a transferred interval with 20 local reference samples; if no more than 2 of the 20 fall outside, the interval is adopted. Testing 20 more people is only needed when 3 or more fall outside, and a new interval (at least 120 people) only if that second set also fails."},
      {"section":"Clinical Chemistry","topic":"Decision Limits Versus Ranges","stem":"Many laboratories report total cholesterol against a target value rather than the central 95% range of the local population. Why?","options":["A target value flags fewer patients as abnormal","Cholesterol has no day-to-day biological variation","The population range includes many people at raised heart disease risk","A population range cannot be calculated for lipids"],"correct":2,"explanation":"For lipids, glucose and HbA1c, clinical decision limits based on outcome studies are more useful than population percentiles, because a \"typical\" level in a population can still carry significant cardiovascular risk. Cholesterol does vary from day to day, and decision limits usually flag more people, not fewer."},
      {"section":"Clinical Chemistry","topic":"EDTA Contamination","stem":"A well outpatient has K 9.2 mmol/L, calcium 0.60 mmol/L and a very low ALP. The serum is not haemolysed. What is the most likely cause?","options":["Collection from an arm with a saline drip","Delay in separating the serum overnight","In-vitro haemolysis during venepuncture","Contamination of the sample with potassium EDTA"],"correct":3,"explanation":"K2/K3 EDTA adds potassium and binds calcium, magnesium and zinc, giving very high potassium, very low calcium and low ALP; it happens when EDTA is carried into the serum tube (wrong order of draw or pouring between tubes). Haemolysis was excluded and would not lower calcium this much."},
      {"section":"Clinical Chemistry","topic":"Drip Arm Contamination","stem":"A ward patient receiving 5% dextrose by IV infusion has glucose 48 mmol/L, sodium 128 mmol/L and potassium 2.8 mmol/L. Urea and creatinine are much lower than yesterday. What is the most likely cause?","options":["Collection into a fluoride oxalate tube by mistake","Hyperosmolar hyperglycaemic state from untreated diabetes","The sample was taken from the arm with the dextrose infusion","In-vitro haemolysis of the sample during collection"],"correct":2,"explanation":"Infusion fluid entering the sample raises the substance in the drip (glucose) and dilutes everything else, so sodium, potassium, urea and creatinine all fall together. A true hyperosmolar state would raise sodium and urea, not lower them; the sample should be repeated from the other arm."},
      {"section":"Clinical Chemistry","topic":"Haemolysis Effects","stem":"A serum sample is visibly red from haemolysis during a difficult blood draw. Which results are most falsely raised?","options":["Sodium, chloride and bicarbonate","Urea, glucose and cholesterol","Albumin, calcium and bilirubin","Potassium, LDH and AST"],"correct":3,"explanation":"Red cells contain much more potassium, LDH and AST than plasma, so their release raises these results strongly; the sample should be recollected. Sodium and chloride are higher in plasma than in red cells, so haemolysis does not raise them."},
      {"section":"Clinical Chemistry","topic":"Ammonia Sample Handling","stem":"A child with suspected liver failure needs a plasma ammonia test. How should the sample be handled?","options":["Fluoride oxalate tube, room temperature, analysed next day","Ammonium heparin tube, room temperature, analysed within 4 hours","Plain tube, left to clot for 1 hour, then centrifuged","EDTA or lithium heparin tube, on ice, analysed within 30 minutes"],"correct":3,"explanation":"Ammonia rises in standing blood as red cells metabolise and amino acids break down, so the sample is kept on ice and analysed quickly. Ammonium heparin adds ammonia to the sample, and clotting at room temperature lets ammonia increase."},
      {"section":"Clinical Chemistry","topic":"Bilirubin and Light","stem":"A neonatal bilirubin sample was left on a sunny window ledge for 3 hours before analysis. What effect is expected?","options":["Falsely high bilirubin from heat-induced haemolysis","Falsely high bilirubin from evaporation in the sun","Falsely low bilirubin from breakdown by light","No effect, because bilirubin is stable in light"],"correct":2,"explanation":"Bilirubin is broken down by light (the same reason phototherapy works), so exposed samples give falsely low results and could hide dangerous neonatal jaundice. Samples should be protected from light, for example by wrapping the tube."},
      {"section":"Histopathology and Laboratory Management","topic":"Risk-Based Biosafety Approach","stem":"According to the WHO Laboratory Biosafety Manual, 4th edition, what should mainly decide which biosafety control measures a lab uses?","options":["Only the risk group of the organism","The number of staff working in the laboratory","The biosafety level printed on the laboratory door","A local risk assessment of the agents and the procedures done"],"correct":3,"explanation":"The 4th edition is built on an evidence-based risk assessment of the agent, the procedures and the local setting, which then decides whether core requirements are enough or heightened measures are needed. Using the risk group alone is the older, simpler approach the manual moves away from."},
      {"section":"Histopathology and Laboratory Management","topic":"Biological Spill Clean-Up","stem":"A blood culture bottle falls and breaks on the lab floor. After putting on gloves and other PPE, how should the spill be cleaned?","options":["Pick up the broken glass by hand, then mop the floor with disinfectant and water","Wipe up the liquid at once with a dry cloth, then spray disinfectant over the floor","Cover with paper towels, pour disinfectant from the edges inward, wait, then lift glass with forceps","Pour alcohol onto the centre of the spill and wipe outward with towels straight away"],"correct":2,"explanation":"Covering the spill and pouring disinfectant from the outside inward contains it, and leaving the right contact time kills the organisms before clean-up; broken glass is picked up with forceps or a dustpan, never by hand. Wiping at once with a dry cloth spreads infectious material before it is disinfected."},
      {"section":"Histopathology and Laboratory Management","topic":"Needle-stick Injury","stem":"A lab technician pricks her finger with a needle used to draw blood from a patient of unknown HIV status. What should she do first?","options":["Squeeze the wound hard and soak it in bleach","Wipe with alcohol, finish her work and report at the end of the week","Wash the site with soap and running water, then report and get assessed for PEP at once","Wait for the patient's HIV result before telling anyone"],"correct":2,"explanation":"First aid is washing with soap and running water, then immediate reporting so that PEP can be started as soon as possible. Squeezing the wound or applying bleach is not recommended and can damage tissue."},
      {"section":"Histopathology and Laboratory Management","topic":"Centrifuge Tube Breakage","stem":"While a centrifuge is running with sputum samples, the technician hears a tube break. What should she do?","options":["Switch off and keep the lid closed (about 30 minutes) so aerosols can settle","Let the run finish, then open the lid to check","Spray disinfectant into the centrifuge while it is still spinning","Open the lid at once to remove the broken tube"],"correct":0,"explanation":"Breakage during spinning creates infectious aerosols, so the motor is switched off and the lid kept closed for about 30 minutes to let them settle before careful clean-up with PPE. Opening the lid at once releases the aerosols into the room."},
      {"section":"Histopathology and Laboratory Management","topic":"Autoclave Validation","stem":"A lab wants to check that its autoclave is truly sterilising infectious waste. Which test gives the best evidence?","options":["A biological indicator with Geobacillus stearothermophilus spores","Weighing the waste before and after the cycle","A colour change on ordinary autoclave tape","Checking that the waste bag is hot after the cycle"],"correct":0,"explanation":"Geobacillus stearothermophilus spores are highly resistant to steam, so their failure to grow after a cycle shows sterilising conditions were reached inside the load. Autoclave tape only shows that the outside reached temperature, not that sterilisation occurred."},
      {"section":"Histopathology and Laboratory Management","topic":"Triple Packaging","stem":"Sputum samples are being sent from a health centre to a reference laboratory. Which description of triple packaging is correct?","options":["Leak-proof secondary bag, then the sample container, then absorbent paper outside","Sample container placed directly into a rigid outer box with ice packs","Leak-proof sample container, absorbent material, leak-proof secondary packaging, then a rigid outer package","Two sample containers taped together inside a plastic bag"],"correct":2,"explanation":"Triple packaging is a watertight primary receptacle, enough absorbent material to soak up any leak, a watertight secondary packaging, and a rigid outer packaging. The option that starts with the secondary bag is tempting because it names leak-proof packaging and absorbent, but the layers are in the wrong order and there is no rigid outer packaging."},
      {"section":"Histopathology and Laboratory Management","topic":"Category B Infectious Substances","stem":"Patient sputum samples for TB testing are being shipped to a reference laboratory. How are they classified for transport?","options":["Biological substance, Category B (UN 3373)","Clinical waste (UN 3291)","Exempt human specimen","Infectious substance affecting humans, Category A (UN 2814)"],"correct":0,"explanation":"Patient specimens sent for diagnosis are normally Category B and packed under UN 3373. Category A (UN 2814) applies to materials such as cultures of M. tuberculosis, which carry a much higher risk."},
      {"section":"Histopathology and Laboratory Management","topic":"Unlabelled Biopsy Specimen","stem":"A cervical biopsy arrives in formalin with a completed request form, but the container has no label. What should the lab do?","options":["Discard it and ask for a repeat biopsy","Keep the specimen, contact the requesting clinician to identify and label it, and record the event","Label the container yourself using the request form","Process it now and add the patient name after reporting"],"correct":1,"explanation":"A biopsy cannot be repeated easily, so it should not be discarded; the person who took it must come and confirm and label it, and the event is recorded as a nonconformity. Labelling it yourself from the form risks giving the wrong patient a diagnosis."},
      {"section":"Histopathology and Laboratory Management","topic":"Waste Colour Coding","stem":"In the WHO colour-coding scheme, where should blood-soaked gauze from a phlebotomy area go?","options":["Yellow bag for infectious waste","Brown bag for chemical waste","Paper box for recyclable waste","Black bag for general waste"],"correct":0,"explanation":"Items contaminated with blood are infectious waste and go in the yellow bag or container. Putting them in the black general-waste bag exposes cleaners and the public to blood-borne infection."},
      {"section":"Histopathology and Laboratory Management","topic":"Sharps Container Use","stem":"When should a sharps container in the phlebotomy room be closed and replaced?","options":["When it is about three-quarters full","At the end of each shift, even if almost empty","When it is half full","Only when it is completely full"],"correct":0,"explanation":"Sharps containers are sealed and replaced at about three-quarters full, so needles cannot stick out and cause injuries. Waiting until completely full is the common mistake that leads to needle-stick injuries."},
      {"section":"Histopathology and Laboratory Management","topic":"Disposal of Culture Plates","stem":"Used bacterial culture plates from the microbiology bench need to be disposed of. What should be done first?","options":["Soak them in tap water overnight","Burn them in an open pit behind the lab","Autoclave them, then dispose of them as treated waste","Put them straight into the general waste bin"],"correct":2,"explanation":"Cultures contain very high numbers of organisms and must be decontaminated, usually by autoclaving, before leaving the lab. Open burning is not a safe or approved treatment method, and general waste must never receive live cultures."},
      {"section":"Histopathology and Laboratory Management","topic":"Formalin Waste Disposal","stem":"The histology lab has several litres of used formalin. How should it be disposed of?","options":["Poured down the sink with plenty of water","Collected as hazardous chemical waste for neutralisation or approved disposal","Left in open containers to evaporate","Mixed into the yellow bags with infectious waste"],"correct":1,"explanation":"Formaldehyde is toxic and a known human carcinogen, so used formalin is collected as chemical waste and neutralised or sent for approved disposal. Pouring it down the sink pollutes the water system and is the most common unsafe practice."},
    ],
  },
];
